import React, { useState, useEffect, useMemo, useCallback, useRef, useContext, createContext } from "react";
import { createRoot } from "react-dom/client";
import { translate, setLang as setI18nLang, getLang, missing as i18nMissing } from "../src/i18n/index.js";
import { computeMargin, defaultRateFor, rateSpreads, sideOf } from "../src/exchange-calc.js";

/* =========================================================================
   OBO FINANCIAL SYSTEM — connected frontend
   Talks to the local API (same origin) started by `npm start` in this
   project. No CDN dependencies, no external chart library — charts are
   small hand-rolled CSS/SVG components so the whole bundle is self-contained.
   ========================================================================= */

const C = {
  navy: "var(--c-navy)", navyDeep: "var(--c-navy-deep)", cyan: "var(--c-cyan)", mint: "var(--c-mint)", brandTintBg: "var(--c-brand-tint-bg)",
  ink: "var(--c-ink)", slate: "var(--c-slate)", paper: "var(--c-paper)", card: "var(--c-card)",
  line: "var(--c-line)", amber: "#c98a2e", amberBg: "#faf1e2", green: "#2f8f6a",
  greenBg: "#e7f4ee", red: "#bd4b3c", redBg: "#fbeae7", slateBg: "#eef3f4",
  // DASHBOARD CHART COLOR FIX round: a dedicated 3-color categorical set for
  // multi-series trend charts (Balance Trends, Money Flow) — kept separate
  // from the status green/red above (still used everywhere for pills,
  // deltas, badges) because those two alone measured a borderline CVD
  // separation (ΔE 6.4, deutan) once actually run through the color-blind
  // simulation, and navy's lightness sat outside the safe band for a
  // categorical line/area chart. This trio (blue/aqua/red) is validated —
  // `node scripts/validate_palette.js "#2a78d6,#1baf7a,#e34948"` — against
  // both the light and dark chart surfaces: every hard gate passes, with the
  // one 6-8 CVD floor pair (red vs. aqua) covered by the legend + hover
  // tooltip + click-to-toggle labels every LineAreaChart series already
  // ships (secondary encoding, not color alone).
  chartBlue: "#2a78d6", chartGreen: "#1baf7a", chartRed: "#e34948",
  // PAYMENT & TRANSFER UPGRADE round: a dedicated, EXACT-hex financial
  // semantic color system for money-moving actions specifically — Deposit
  // (money in), Withdraw (money out), and Transfer (a neutral, brand-colored
  // action between two accounts). Deliberately separate constants from the
  // softer green/red/amber above (still used everywhere else — status pills,
  // deltas, badges) rather than repainting those, per the spec's own scope:
  // only the Payment/Transfer/Transaction-History/Account-Statement surfaces
  // this round actually touches adopt these; nothing else in the app changes
  // color just because these constants now exist.
  depositGreen: "#16A34A", depositGreenHover: "#15803D",
  depositGreenBg: "rgba(22,163,74,0.08)", depositBadgeBg: "rgba(22,163,74,0.12)", depositBadgeText: "#15803D",
  withdrawRed: "#DC2626", withdrawRedHover: "#B91C1C",
  withdrawRedBg: "rgba(220,38,38,0.08)", withdrawBadgeBg: "rgba(220,38,38,0.12)", withdrawBadgeText: "#B91C1C",
  // BRAND COLOR CONSISTENCY round: Transfer is the brand-coloured action,
  // so it now follows the active Brand Theme instead of fixed emerald.
  transferTeal: "var(--c-navy-light)", transferTealHover: "var(--c-navy)", transferIcon: "var(--c-cyan)",
  transferTealBg: "color-mix(in srgb, var(--c-cyan) 8%, transparent)", transferBadgeBg: "color-mix(in srgb, var(--c-cyan) 12%, transparent)", transferBadgeText: "var(--c-navy)",
  balancePositive: "#16A34A", balanceNegative: "#DC2626",
  validationRedBorder: "#DC2626", validationRedText: "#B91C1C", validationRedBg: "rgba(220,38,38,0.06)",
  successGreenBorder: "#16A34A", successGreenText: "#15803D",
};
// Only the core surface/text tokens above vary with the Dark/White toggle
// (via CSS custom properties, defined below). Brand and semantic colors stay
// constant in both themes — they're already legible on both light and dark
// surfaces, and keeping them fixed avoids introducing contrast regressions
// across the ~40 components that reference them throughout this file.
// (navy is the one exception: it's used as both a background — e.g. the
// sidebar — and as foreground text/borders elsewhere, e.g. "ghost" buttons.
// A single fixed shade can't have good contrast in both roles on both
// themes, so navy gets a modestly brighter dark-mode value.)
const THEME_CSS = `
  :root {
    /* APPEARANCE & BRANDING round 2: theme-independent defaults (unlike the
       light/dark surface tokens below, these five don't change between
       Light and Dark mode — matching how brand_color already behaved in
       Round 1). App()'s effects override them inline on <html> once a
       Super Admin sets a custom value; removed (falling back to these
       defaults) when unset. */
    /* BRAND COLOR MANAGEMENT round: an uncustomized install's static default
       is now the Emerald Finance theme (spec: "This is the DEFAULT theme"),
       replacing the old hand-picked navy/cyan/mint. Any install that already
       has a company.brandColor saved is unaffected — App()'s brand-color
       effects override every one of these inline before first paint. */
    --c-cyan: #00b98a; --c-cyan-bright: #00d7a0; --c-mint: #00c99a; --c-text-on-primary: #ffffff; --c-text-on-accent: #0d2436;
    --c-cyan-rgb: 0, 185, 138; --c-cyan-bright-rgb: 0, 215, 160;
    --c-status-pending: #c98a2e; --c-status-paid: #2f8f6a; --c-status-refunded: #42bfdd;
    /* POPPINS TABLE DESIGN round: Poppins is now the system default (was
       Inter) — see FONT_FAMILY_OPTIONS above for the full rationale. */
    --c-font-family: "Poppins", "Segoe UI", Arial, sans-serif;
    --c-zoom: 1;
  }
  html { zoom: var(--c-zoom); }
  /* TEAL REBRAND round: by explicit request, the system's brand palette
     moves from dark green (#004c3d) to the premium teal/emerald palette
     from the uploaded Transaction History spec — applied system-wide (not
     just one page) since every surface (sidebar, buttons, active tabs,
     links, table headers/footers, login gradient, card accent borders)
     already reads these same few tokens (--c-navy/--c-navy-deep/
     --c-navy-light/--c-thead-bg/--c-tfoot-bg), so one edit here recolors
     the whole app consistently. Installations with a custom Brand Color set
     in Settings -> Appearance & Branding still override these (see the
     brandColor useEffect below) — this is only the new, teal, no-custom-
     brand-color default. */
  :root, [data-theme="light"] {
    --c-card: #ffffff; --c-ink: #173042; --c-slate: #607d8b;
    --c-navy: #00695c; --c-navy-deep: #00574b; --c-navy-light: #00897b; --c-navy-light-rgb: 0, 137, 123;
    --c-thead-bg: #00695c; --c-thead-fg: #ffffff; --c-row-bg: #ffffff; --c-tfoot-bg: #00695c; --c-tfoot-fg: #ffffff;
    /* BRAND COLOR CONSISTENCY round: these tinted surfaces used to be fixed
       green-greys (#f5f9f8 / #d7e3e0 / #edf4f3 / #e5f0ee), so with any other
       Brand Theme the page background, borders, row hover and card tint
       stayed green. They are now mixed from --c-navy, which the Brand Theme
       sets at runtime; with the default theme they look the same as before. */
    --c-paper: color-mix(in srgb, var(--c-navy) 4%, #f8fafa);
    --c-line: color-mix(in srgb, var(--c-navy) 10%, #dce2e4);
    --c-row-hover: color-mix(in srgb, var(--c-navy) 7%, #ffffff);
    --c-brand-tint-bg: color-mix(in srgb, var(--c-navy) 10%, #f7f9f9);
  }
  [data-theme="dark"] {
    --c-ink: #e8eef1; --c-slate: #95a5ad;
    --c-navy: #1db8a3; --c-navy-deep: #00574b; --c-navy-light: #00897b;
    --c-thead-bg: #0c4a40; --c-thead-fg: #eaf7f4; --c-row-bg: var(--c-card); --c-tfoot-bg: #0f5c4e; --c-tfoot-fg: #eaf7f4;
    --c-paper: color-mix(in srgb, var(--c-navy-deep) 14%, #0d1214);
    --c-card: color-mix(in srgb, var(--c-navy-deep) 16%, #131a1c);
    --c-line: color-mix(in srgb, var(--c-navy) 16%, #222b2e);
    --c-row-hover: color-mix(in srgb, var(--c-navy) 14%, #131a1c);
    --c-brand-tint-bg: color-mix(in srgb, var(--c-navy) 13%, #131a1c);
  }
  [data-theme="dark"] input, [data-theme="dark"] select, [data-theme="dark"] textarea {
    color-scheme: dark;
  }

  /* --- Modern table system: shared by every table via the .gk-table class --- */
  .gk-table tbody tr { transition: background-color 0.12s ease; background: var(--c-row-bg); }
  .gk-table tbody tr:hover { background: var(--c-row-hover); }
  /* CUSTOMERS TABLE REDESIGN round: compact horizontal padding + vertically
     centred rows so all ten columns fit a laptop screen without scrolling. */
  .gk-customers-table th, .gk-customers-table td { padding-left: 8px !important; padding-right: 8px !important; vertical-align: middle !important; }
  .gk-customers-table th { letter-spacing: 0.02em !important; font-size: 11.5px !important; }
  .gk-badge-active { color: #15803D; } .gk-badge-inactive { color: #B91C1C; }
  [data-theme="dark"] .gk-badge-active { color: #4ADE80; background: rgba(74,222,128,0.14) !important; }
  [data-theme="dark"] .gk-badge-inactive { color: #F87171; background: rgba(248,113,113,0.14) !important; }
  .gk-row-icon-btn { transition: background-color 0.12s ease, border-color 0.12s ease; }
  .gk-row-icon-btn:hover { background: color-mix(in srgb, var(--c-navy) 10%, transparent) !important; border-color: var(--c-navy) !important; }
  .gk-row-icon-btn-danger:hover { background: rgba(220,38,38,0.08) !important; border-color: #DC2626 !important; }
  .gk-row-icon-btn:focus-visible { outline: 2px solid var(--c-navy); outline-offset: 2px; }
  /* POPPINS TABLE DESIGN round: added overflow:hidden so the wrap's own
     rounded corners clip the dark header's square top corners cleanly
     (spec section 12: "the table should feel like one professional
     component"), instead of the header bleeding past them. */
  .gk-table-wrap { border-radius: 8px; box-shadow: 0 1px 2px rgba(8,20,30,0.04); overflow: hidden; }

  /* RESIZABLE TABLE COLUMNS round: a subtle drag handle on each header
     cell's right edge — invisible until the header (or the handle itself)
     is hovered/dragged, so it never visually competes with the header text
     (spec section 4: "easy to grab without making it visually distracting"). */
  .gk-table th { position: relative; }
  /* Flush with the cell's own right edge (never bleeding into the next
     header cell) — two adjacent sticky <th> elements each start their own
     stacking context, so a handle that overhangs into the neighboring
     cell's box can end up visually and pointer-wise UNDER that next cell
     instead of on top of it. Keeping the hit area fully inside its own
     cell avoids that entirely. */
  .gk-col-resize-handle { position: absolute; top: 0; right: 0; bottom: 0; width: 10px; cursor: col-resize; z-index: 3; touch-action: none; }
  .gk-col-resize-handle::after { content: ""; position: absolute; top: 18%; bottom: 18%; right: 3px; width: 2px; border-radius: 2px; background: transparent; transition: background-color 0.15s ease; }
  .gk-table th:hover .gk-col-resize-handle::after, .gk-col-resize-handle:hover::after, .gk-col-resize-handle:active::after { background: rgba(255,255,255,0.4); }

  /* --- Icon micro-animations --- */
  .gk-icon-btn { transition: transform 0.15s ease, background-color 0.15s ease, color 0.15s ease; }
  .gk-icon-btn:hover { transform: translateY(-1px); }
  /* BRAND COLOR MANAGEMENT round: primary/accent buttons react to the active
     brand theme's Primary Light/Dark and Accent Bright tokens on hover/press
     (spec section 12), instead of a flat, unreactive fill. */
  .gk-btn-primary:hover:not(:disabled) { background: var(--c-navy-light) !important; border-color: var(--c-navy-light) !important; }
  .gk-btn-primary:active:not(:disabled) { background: var(--c-navy-deep) !important; border-color: var(--c-navy-deep) !important; }
  .gk-btn-accent:hover:not(:disabled) { background: var(--c-cyan-bright) !important; border-color: var(--c-cyan-bright) !important; }
  .gk-btn-accent:active:not(:disabled) { filter: brightness(0.92); }
  /* PAYMENT & TRANSFER UPGRADE round: Deposit/Withdraw/Transfer get their own
     fixed hover shades (never the brand's Primary Light, since these three
     colors carry financial meaning — green/red/teal — independent of theme). */
  .gk-btn-deposit:hover:not(:disabled) { background: #15803D !important; border-color: #15803D !important; }
  .gk-btn-withdraw:hover:not(:disabled) { background: #B91C1C !important; border-color: #B91C1C !important; }
  .gk-btn-transfer:hover:not(:disabled) { background: var(--c-navy) !important; border-color: var(--c-navy) !important; }
  /* BACK NAVIGATION round: one dark-red treatment for every Back control.
     --c-back: solid fill / outline colour, --c-back-hover: darker press/hover. */
  :root { --c-back: #8B0000; --c-back-hover: #700000; --c-back-text: #8B0000; --c-back-tint: rgba(139,0,0,0.08); }
  [data-theme="dark"] { --c-back-text: #FF8A8A; --c-back-tint: rgba(255,138,138,0.12); }
  .gk-btn-back { background: var(--c-back) !important; border-color: var(--c-back) !important; color: #FFFFFF !important; }
  .gk-btn-back:hover:not(:disabled) { background: var(--c-back-hover) !important; border-color: var(--c-back-hover) !important; }
  .gk-btn-back-outline { background: transparent !important; border-color: var(--c-back-text) !important; color: var(--c-back-text) !important; }
  .gk-btn-back-outline:hover:not(:disabled) { background: var(--c-back-tint) !important; border-color: var(--c-back-hover) !important; }
  [data-theme="dark"] .gk-btn-back-outline:hover:not(:disabled) { border-color: var(--c-back-text) !important; }
  .gk-back-link { background: none !important; color: var(--c-back-text) !important; }
  .gk-back-link:hover { background: var(--c-back-tint) !important; }
  .gk-btn-back:focus-visible, .gk-btn-back-outline:focus-visible, .gk-back-link:focus-visible { outline: 2px solid var(--c-back-text); outline-offset: 2px; }
  .gk-icon-btn.gk-danger:hover svg { animation: gk-shake 0.4s ease; }
  .gk-icon-btn.gk-download:hover svg { animation: gk-bounce-down 0.5s ease; }
  .gk-sort-arrow { display: inline-block; transition: transform 0.18s ease, opacity 0.18s ease; }
  .gk-search-input { transition: box-shadow 0.15s ease, border-color 0.15s ease; }
  .gk-search-input:focus { box-shadow: 0 0 0 3px color-mix(in srgb, var(--c-cyan) 25%, transparent); }
  /* ACCOUNT VIEW PREMIUM REDESIGN round: emerald focus state for the Account
     View's transaction filter inputs (spec section 6) — scoped to this one
     class so it never changes focus styling on inputs/selects elsewhere. */
  .gk-acct-filter-input:focus { outline: none; border-color: var(--c-cyan) !important; box-shadow: 0 0 0 3px color-mix(in srgb, var(--c-cyan) 20%, transparent); }
  /* Close button (×): neutral by default, a soft red hover — never visually
     dominant, matches the "premium financial UI" close-control spec. Purely
     cosmetic, applies wherever Modal's own close button is used. */
  .gk-modal-close:hover { background: rgba(220,38,38,0.08) !important; color: #DC2626 !important; }
  /* ACCOUNT VIEW PREMIUM REDESIGN round: KPI grid collapses to 2 columns on
     tablet and 1 on narrow/mobile widths (spec section 17), matching the
     modal's own "desktop-first, responsive on smaller screens" requirement. */
  .gk-acct-kpi-grid { display: grid; grid-template-columns: repeat(4, 1fr); }
  @media (max-width: 900px) { .gk-acct-kpi-grid { grid-template-columns: repeat(2, 1fr); } }
  @media (max-width: 480px) { .gk-acct-kpi-grid { grid-template-columns: 1fr; } }
  /* ACCOUNT VIEW TABBED REDESIGN round: Customer Information's two-column
     layout collapses to one column on tablet/mobile — Customer Details,
     Account Status, Quick Actions, Linked Account stack in that order
     (spec section 13), matching the DOM order the two columns are already
     written in. */
  @media (max-width: 800px) { .gk-acct-info-grid { grid-template-columns: 1fr !important; } }
  /* TRANSACTION MODAL REDESIGN round: the Deposit/Withdraw card pair and the
     paired Amount/Payment Date and Cash in Hand/Reference field rows all
     stack to a single column on narrow screens (spec section 9), instead of
     ever forcing the modal wider than the viewport. */
  @media (max-width: 560px) { .gk-txtype-grid, .gk-tx-field-row { grid-template-columns: 1fr !important; } }
  /* BALANCE SHEET round: four cards on desktop, two on tablets, one on phones. */
  @media (max-width: 1150px) { .gk-bs-grid, .gk-cash-cards { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; } }
  @media (max-width: 600px) { .gk-bs-grid, .gk-cash-cards { grid-template-columns: minmax(0, 1fr) !important; } }
  /* COMPANY EXPENSES round: the expense form is one column on phones. */
  @media (max-width: 560px) { .gk-exp-form-grid { grid-template-columns: 1fr !important; } .gk-exp-filters > * { width: 100% !important; } .gk-exp-add { margin-left: 0 !important; } .gk-exp-add button { width: 100%; justify-content: center; } }
  /* Expense charts: side by side on desktop, stacked on tablets/phones. */
  .gk-dash-section .gk-balance-sheet, .gk-dash-section .gk-cash-cards, .gk-dash-section .gk-exp-charts { margin-bottom: 0 !important; }
@media (max-width: 1000px) { .gk-exp-charts { grid-template-columns: minmax(0, 1fr) !important; } }
  @media (max-width: 480px) { .gk-exp-chart-body { grid-template-columns: minmax(0, 1fr) !important; } }
  /* ACCOUNT VIEW COMPACT HEADER round: on narrow screens the left identity
     block and right balance block stack instead of sitting side by side,
     and the balance block switches from right-aligned to left-aligned so it
     reads naturally when stacked underneath. */
  @media (max-width: 560px) {
    .gk-acct-header-row { flex-direction: column; align-items: flex-start !important; gap: 8px !important; }
    .gk-acct-header-balance { text-align: left !important; }
  }
  .gk-settings-icon { transition: transform 0.35s ease; }
  .gk-settings-icon:hover { transform: rotate(75deg); }
  .gk-account-name-link { transition: color 0.12s ease; }
  .gk-account-name-link:hover { text-decoration: underline; }
  .gk-account-name-arrow { display: inline-block; opacity: 0; transform: translateX(-3px); transition: opacity 0.15s ease, transform 0.15s ease; }
  .gk-account-name-link:hover .gk-account-name-arrow { opacity: 1; transform: translateX(0); }
  @media (max-width: 480px) { .gk-profile-text { display: none; } }
  /* MENU TRANSITIONS & MICRO-INTERACTIONS round: chevron rotation tightened
     to the spec's 180ms ease-in-out (was 200ms ease); everything else about
     the chevron — its markup, its [data-open] toggle, where it's used — is
     unchanged. */
  .gk-nav-chevron { transition: transform 0.18s ease-in-out; flex-shrink: 0; margin-left: auto; }
  .gk-nav-chevron[data-open="true"] { transform: rotate(90deg); }
  /* Submenu open/close now animates a translateY alongside the existing
     max-height/opacity hack (max-height stays because "height: auto" isn't
     animatable — same technique as before, just extended). */
  .gk-submenu { overflow: hidden; transition: max-height 0.22s ease-out, opacity 0.22s ease-out, transform 0.22s ease-out; max-height: 0; opacity: 0; transform: translateY(-6px); }
  .gk-submenu[data-open="true"] { max-height: 220px; opacity: 1; transform: translateY(0); }
  /* Submenu items stagger in on open (subtle: opacity+translateX, no
     bounce). The animation is only declared under [data-open="true"], so it
     replays from scratch every time a group is reopened rather than once on
     first mount. Nth-child delays are small and capped — every group in
     this app has 2-3 children, so a 4th+ item just reuses the last delay. */
  @keyframes gk-submenu-item-in { from { opacity: 0; transform: translateX(-5px); } to { opacity: 1; transform: translateX(0); } }
  .gk-submenu[data-open="true"] .gk-submenu-indent > button { animation: gk-submenu-item-in 200ms ease-out both; }
  .gk-submenu[data-open="true"] .gk-submenu-indent > button:nth-child(1) { animation-delay: 30ms; }
  .gk-submenu[data-open="true"] .gk-submenu-indent > button:nth-child(2) { animation-delay: 60ms; }
  .gk-submenu[data-open="true"] .gk-submenu-indent > button:nth-child(n+3) { animation-delay: 90ms; }
  .gk-nav-group-header { transition: background-color 0.22s cubic-bezier(0.4,0,0.2,1), color 0.18s ease-out; }
  .gk-nav-group-header:not([data-active="true"]):hover { background: rgba(255,255,255,0.08); color: #fff; }
  .gk-sidebar[data-collapsed="true"] .gk-nav-chevron,
  .gk-sidebar[data-collapsed="true"] .gk-submenu-indent { display: none; }
  .gk-sidebar[data-collapsed="true"] .gk-submenu { max-height: none !important; opacity: 1 !important; overflow: visible; }
  @media (max-width: 768px) {
    .gk-sidebar[data-collapsed="true"] .gk-nav-chevron,
    .gk-sidebar[data-collapsed="true"] .gk-submenu-indent { display: flex; }
  }
  .gk-spin { animation: gk-spin 0.9s linear infinite; }
  @keyframes gk-shake { 0%,100% { transform: translateX(0); } 20% { transform: translateX(-2px) rotate(-4deg); } 40% { transform: translateX(2px) rotate(4deg); } 60% { transform: translateX(-1px); } 80% { transform: translateX(1px); } }
  @keyframes gk-bounce-down { 0%,100% { transform: translateY(0); } 40% { transform: translateY(2.5px); } 60% { transform: translateY(-1px); } }
  @keyframes gk-spin { to { transform: rotate(360deg); } }
  @keyframes gk-pulse { 0%,100% { opacity: 1; } 50% { opacity: 0.45; } }
  /* Badge value-change pulse (spec: 12 -> 13 style count bump). Applied via
     a key-remount on the badge span itself, so it only replays when the
     count actually changes, not on every unrelated re-render. */
  @keyframes gk-badge-in { from { opacity: 0; transform: scale(0.85); } to { opacity: 1; transform: scale(1); } }
  .gk-badge-anim { animation: gk-badge-in 180ms ease-out; }
  /* BULK TRANSACTION WORKSPACE — EMERALD/TEAL REDESIGN round: a scoped
     focus-ring for the Add Transaction form's inputs only (class applied
     directly on each Input/Select/TextArea instance inside
     BulkTransactionWorkspace) — :focus can't be expressed as an inline
     style, so this one rule lives here instead of touching the shared
     Input/Select/TextArea components' own default styling, which every
     other form in the app also uses and must stay exactly as it was. */
  .gk-bulk-mint-input:focus { border-color: var(--c-navy) !important; box-shadow: 0 0 0 3px color-mix(in srgb, var(--c-navy) 14%, transparent); }
  .gk-bulk-mint-input::placeholder { color: var(--c-slate); opacity: 0.85; }

  /* COLLAPSIBLE NOTES round: every optional Notes field (OptionalNotes) is a
     compact, closed section until the user opens it. Brand accents follow the
     active Brand Theme (--c-navy), like every other form control. */
  /* MARK AS PAID round */
  .gk-qx-paid { margin-top: 12px; border: 1px solid var(--c-line); border-radius: 10px; background: var(--c-card); padding: 10px 12px; }
  .gk-qx-paid[data-on="true"] { border-color: color-mix(in srgb, var(--c-navy) 40%, var(--c-line)); background: color-mix(in srgb, var(--c-navy) 4%, var(--c-card)); }
  .gk-qx-paid-toggle { display: flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 700; color: var(--c-ink); cursor: pointer; }
  .gk-qx-paid-toggle input { width: 16px; height: 16px; accent-color: var(--c-navy); cursor: pointer; }
  .gk-qx-paid-toggle input:disabled { cursor: not-allowed; }
  .gk-qx-paid-body { display: flex; flex-direction: column; gap: 7px; margin-top: 10px; }
  .gk-qx-paid-row { display: flex; justify-content: space-between; gap: 10px; font-size: 12px; color: var(--c-slate); }
  .gk-qx-paid-row b { color: var(--c-ink); text-align: right; min-width: 0; overflow-wrap: anywhere; }
  .gk-qx-paid-note { font-size: 11px; color: var(--c-slate); background: var(--c-paper); border-radius: 6px; padding: 6px 8px; }
  .gk-qx-paid-label { display: block; font-size: 11.5px; font-weight: 600; color: var(--c-ink); margin: 4px 0 4px; }
  .gk-qx-paid-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
  .gk-qx-paid-hint { font-size: 11px; color: var(--c-slate); margin-top: 3px; }
  .gk-qx-paid-err { font-size: 11px; color: #DC2626; margin-top: 3px; }
  @media (max-width: 420px) { .gk-qx-paid-grid { grid-template-columns: 1fr; } }
  /* CUSTOMER TRANSACTION SELECTOR round */
  .gk-qx-viewtx { display: inline-flex; align-items: center; gap: 5px; font: inherit; font-size: 11px; font-weight: 600; color: var(--c-navy); background: color-mix(in srgb, var(--c-navy) 7%, transparent); border: 1px solid color-mix(in srgb, var(--c-navy) 30%, transparent); border-radius: 999px; padding: 3px 4px 3px 9px; cursor: pointer; }
  .gk-qx-viewtx:hover:not(:disabled) { background: color-mix(in srgb, var(--c-navy) 12%, transparent); }
  .gk-qx-viewtx:focus-visible { outline: 2px solid var(--c-navy); outline-offset: 1px; }
  .gk-qx-viewtx:disabled { opacity: .55; cursor: not-allowed; }
  .gk-qx-viewtx-count { min-width: 18px; text-align: center; background: var(--c-navy); color: #fff; border-radius: 999px; padding: 0 6px; font-size: 10.5px; line-height: 16px; }
  @media (max-width: 640px) {
    .gk-fund-table thead { display: none; }
    .gk-fund-table, .gk-fund-table tbody, .gk-fund-table tr, .gk-fund-table td { display: block; width: 100% !important; box-sizing: border-box; }
    .gk-fund-table tr { border-bottom: 1px solid var(--c-line); padding: 6px 0; }
    .gk-fund-table td { border: 0 !important; padding: 3px 14px !important; text-align: left !important; max-width: none !important; white-space: normal !important; }
    .gk-fund-table td[data-label]::before { content: attr(data-label); display: inline-block; min-width: 86px; font-size: 10.5px; font-weight: 700; color: var(--c-slate); text-transform: uppercase; }
  }
  .gk-notes { border: 1px solid var(--c-line); border-radius: 8px; background: color-mix(in srgb, var(--c-paper) 65%, var(--c-card)); min-width: 0; max-width: 100%; box-sizing: border-box; transition: border-color .15s ease; }
  .gk-notes[data-open="true"] { border-color: color-mix(in srgb, var(--c-navy) 35%, var(--c-line)); background: var(--c-card); }
  .gk-notes-head { display: flex; align-items: center; gap: 7px; width: 100%; min-width: 0; box-sizing: border-box; background: none; border: 0; border-radius: 8px; padding: 7px 10px; cursor: pointer; font-family: inherit; font-size: 12px; font-weight: 600; line-height: 1.3; color: var(--c-ink); text-align: left; }
  .gk-notes-head:hover:not(:disabled) { background: color-mix(in srgb, var(--c-navy) 5%, transparent); }
  .gk-notes-head:focus-visible { outline: 2px solid var(--c-navy); outline-offset: -2px; }
  .gk-notes-head:disabled { cursor: default; opacity: .7; }
  .gk-notes-icon { color: var(--c-navy); display: inline-flex; flex-shrink: 0; }
  .gk-notes-label { flex-shrink: 0; white-space: nowrap; }
  .gk-notes-preview { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--c-slate); font-weight: 400; }
  .gk-notes-chev { margin-left: auto; color: var(--c-slate); display: inline-flex; flex-shrink: 0; transition: transform .18s ease; }
  .gk-notes[data-open="true"] .gk-notes-chev { transform: rotate(180deg); color: var(--c-navy); }
  .gk-notes-body { padding: 0 10px 10px; animation: gk-notes-in .18s ease-out both; }
  @keyframes gk-notes-in { from { opacity: 0; transform: translateY(-3px); } to { opacity: 1; transform: none; } }

  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after { animation-duration: 0.001ms !important; animation-iteration-count: 1 !important; transition-duration: 0.001ms !important; scroll-behavior: auto !important; }
  }

  /* --- Collapsible sidebar --- */
  /* FIXED/STICKY SIDEBAR round: the sidebar is now pinned to the viewport on
     desktop (position: sticky + top:0 + its own height:100vh, with
     align-self:flex-start so the flex row's default stretch never fights
     the explicit height) instead of just being a normal-height flex child
     that scrolled away with the rest of the page. Nothing about its width,
     colors, animation, or collapse behavior changes — only "sticks" where it
     already sat. The mobile media query below still overrides this to its
     own position:fixed drawer, unchanged and unaffected by this rule. */
  .gk-sidebar {
    width: 208px; flex-shrink: 0; display: flex; flex-direction: column;
    transition: width 0.24s cubic-bezier(0.4,0,0.2,1), transform 0.24s cubic-bezier(0.4,0,0.2,1);
    overflow: hidden; position: sticky; top: 0; align-self: flex-start; height: calc(100vh / var(--c-zoom, 1)); height: calc(100dvh / var(--c-zoom, 1)); z-index: 60;
    border-right: 1px solid rgba(255,255,255,0.06);
  }
  /* The nav list is the ONLY part that scrolls internally when the menu is
     taller than the viewport — header and footer stay put (spec items 3/4).
     min-height:0 is required here: without it a flex column child never
     shrinks below its content's natural height, so overflow-y:auto would
     never actually kick in. */
  /* SIDEBAR LAYOUT FIX round: 100dvh (above) is the height actually visible
     on phones/tablets, so the OBO TECH footer is never pushed under the
     browser's address bar; 100vh stays as the fallback for older browsers.
     The main column clips anything wider than the screen to itself, so one
     over-wide value or table can never make the whole page scroll sideways
     (which slid the sidebar out of view and left a blank strip). "clip"
     — not "hidden" — so sticky headers inside the page keep working; tables
     keep their own horizontal scroll. */
  .gk-main-col { overflow-x: clip; }
  /* The Font Size setting zooms the whole page (html { zoom }), and the
     browser zooms vh units with it — so at "Small" a plain 100vh sidebar
     ended short of the screen bottom, and at "Large" it ran past it. Dividing
     by the same --c-zoom gives exactly the visible height at every size. */
  .gk-shell { min-height: calc(100vh / var(--c-zoom, 1)) !important; min-height: calc(100dvh / var(--c-zoom, 1)) !important; }
  .gk-sidebar-footer { flex-shrink: 0; }
  .gk-sidebar-header { flex-shrink: 0; }
  .gk-sidebar-nav {
    flex: 1; min-height: 0; overflow-y: auto;
    scrollbar-width: thin; scrollbar-color: rgba(var(--c-cyan-bright-rgb, 0,215,160), 0.55) transparent;
  }
  .gk-sidebar-nav::-webkit-scrollbar { width: 6px; }
  .gk-sidebar-nav::-webkit-scrollbar-track { background: transparent; }
  .gk-sidebar-nav::-webkit-scrollbar-thumb {
    background: rgba(var(--c-cyan-bright-rgb, 0,215,160), 0.4); border-radius: 3px;
  }
  .gk-sidebar-nav::-webkit-scrollbar-thumb:hover { background: rgba(var(--c-cyan-bright-rgb, 0,215,160), 0.65); }
  /* BRAND COLOR MANAGEMENT round: a very subtle decorative wash toward the
     bottom-right corner, themed automatically from the active theme's Accent
     / Accent Bright (via their -rgb custom properties) at low opacity — pure
     decoration on its own layer (z-index:0, pointer-events:none), sitting
     behind the nav content (z-index:1 below) so it never interferes with
     text, icons, or clicks. */
  .gk-sidebar::after {
    content: ""; position: absolute; inset: 0; z-index: 0; pointer-events: none;
    background:
      radial-gradient(140% 90% at 100% 100%, rgba(var(--c-cyan-bright-rgb, 0,215,160), 0.10) 0%, transparent 55%),
      radial-gradient(120% 70% at 100% 85%, rgba(var(--c-cyan-rgb, 0,185,138), 0.12) 0%, transparent 60%);
  }
  .gk-sidebar > * { position: relative; z-index: 1; }
  .gk-sidebar[data-collapsed="true"] { width: 64px; }
  /* FIX: collapsed sidebar is only 64px wide — the header row used to keep
     BOTH the brand logo and the collapse/expand (☰) toggle side by side,
     which needs ~100px+ and made the toggle button get pushed outside the
     64px box and clipped by .gk-sidebar's overflow:hidden. That's what made
     the toggle unreachable once collapsed (no way back to expanded). Fix:
     when collapsed, hide the logo and center just the toggle button in the
     header, same icon-only-rail idea the nav buttons already use below. */
  .gk-sidebar[data-collapsed="true"] .gk-sidebar-header {
    justify-content: center; padding-left: 0; padding-right: 0; gap: 0;
  }
  /* BRAND HEADER NAVIGATION round: very subtle hover feedback now that the
     whole header row is a "go to Dashboard" click target — a faint white
     wash, never a bright or animated effect, and no layout shift. Applies
     equally in expanded and collapsed (icon-only) rail states. */
  .gk-brand-header-link { transition: background 180ms ease; }
  .gk-brand-header-link:hover, .gk-brand-header-link:focus-visible { background: rgba(255,255,255,0.03); }
  .gk-sidebar[data-collapsed="true"] .gk-brand-logo-wrap { display: none; }
  /* FIX: .gk-brand-name uses white-space:normal + overflow-wrap:anywhere so
     a long Company Name can wrap onto 2 lines (never ellipsize) — but that
     means when .gk-brand-text's width animates down to 0 on collapse, the
     browser wraps the name ONE CHARACTER PER LINE instead of just going
     invisible, which exploded this row to ~700px tall and pushed the whole
     nav list off-screen below the fold (the sidebar looked empty/broken).
     max-height:0 + overflow:hidden here clips it fully regardless of how
     many lines that character-by-character wrap produces. */
  .gk-sidebar[data-collapsed="true"] .gk-brand-text { max-height: 0; overflow: hidden; }
  /* Section 1/10: labels/brand/footer text fade+slide out immediately when
     collapsing (transition-delay: 0), but fade+slide IN only after a short
     delay when expanding, so text doesn't pop into view while the sidebar
     is still narrow — icons themselves never move, only these text nodes. */
  .gk-nav-label, .gk-brand-text, .gk-sidebar-footer-text {
    transition: opacity 0.18s ease 0.1s, max-width 0.24s cubic-bezier(0.4,0,0.2,1), transform 0.18s ease 0.1s;
    opacity: 1; transform: translateX(0); overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
  }
  /* RESPONSIVE BRAND NAME round: the Company Name (and its subtitle) must
     never be cut, hidden, or ellipsized (spec sections 1/3/10) — override
     the nowrap/ellipsis the rule above sets for its own .gk-brand-text
     wrapper (still needed there, unchanged, for the nav-label collapse-fade
     animation). Wrapping to a natural 2 lines is handled by the wrapper's
     own width — see sidebarWidthPx in App() — not by anything here. */
  .gk-brand-name {
    white-space: normal; overflow: visible; text-overflow: unset;
    overflow-wrap: anywhere; word-break: normal;
  }
  .gk-sidebar[data-collapsed="true"] .gk-nav-label,
  .gk-sidebar[data-collapsed="true"] .gk-brand-text,
  .gk-sidebar[data-collapsed="true"] .gk-sidebar-footer-text {
    opacity: 0; max-width: 0; transform: translateX(-8px);
    transition: opacity 0.15s ease, max-width 0.24s cubic-bezier(0.4,0,0.2,1), transform 0.15s ease;
  }
  /* SIDEBAR TYPOGRAPHY/HEIGHT INDEPENDENCE round: a nav button's height used
     to come ONLY from its padding + the font's own line-height, so sizing
     the label text down (or up) directly changed how tall every menu item
     was, which in turn changed how much of the 100vh sidebar the nav list
     visually filled (the sidebar box itself was always height:100vh — see
     .gk-sidebar above — but the row heights inside it weren't fixed). A
     min-height here (46px main item, 40px submenu item just below) is a
     floor the box can never shrink under regardless of font-size, while
     align-items:center (unchanged) keeps icon + label + chevron vertically
     centered within that floor either way. Growing past the floor for an
     unusually large font is still allowed — only shrinking below it isn't.
  */
  .gk-nav-btn {
    display: flex; align-items: center; gap: 10px; white-space: nowrap; color: #cfe3ea; background: none;
    min-height: 46px; box-sizing: border-box;
    transition: background-color 0.22s cubic-bezier(0.4,0,0.2,1), color 0.18s ease-out;
  }
  .gk-nav-btn:not([data-active="true"]):hover { background: rgba(255,255,255,0.08); color: #fff; }
  .gk-nav-btn:active { transform: scale(0.985); transition: transform 80ms ease; }
  .gk-submenu-indent .gk-nav-btn { color: #b9d4dd; min-height: 40px; }
  /* BRAND COLOR MANAGEMENT round: a small themed node on the connector line
     at each submenu item (spec section 9/11/12), drawn as a ::before dot so
     it needs no extra markup — purely decorative, sized off the line it
     sits on rather than the button's own box. */
  .gk-submenu-indent .gk-nav-btn::before {
    content: ""; position: absolute; left: -17px; top: 50%; transform: translateY(-50%);
    width: 6px; height: 6px; border-radius: 50%; background: var(--c-cyan-bright);
    box-shadow: 0 0 0 2px var(--c-navy);
  }
  /* Icon + chevron nudge on hover (spec 2/7): translate+scale via a
     will-change hint, transform/opacity only, never width/height. The
     Settings gear keeps its own existing rotate-on-direct-hover animation
     untouched (.gk-settings-icon:hover, defined elsewhere) — excluded here
     so the two don't fight over the transform property. */
  .gk-nav-icon { transition: transform 0.18s ease-out, color 0.18s ease-out; will-change: transform; }
  .gk-nav-btn:hover .gk-nav-icon:not(.gk-settings-icon) { transform: translateX(2px) scale(1.05); color: var(--c-cyan); }
  .gk-nav-btn:hover .gk-nav-chevron:not([data-open="true"]) { transform: translateX(3px); }
  .gk-sidebar[data-collapsed="true"] .gk-nav-btn { justify-content: center; padding-left: 0 !important; padding-right: 0 !important; }
  .gk-sidebar-toggle {
    background: rgba(255,255,255,0.1); border: 1px solid rgba(255,255,255,0.2); color: #fff;
    width: 32px; height: 32px; border-radius: 7px; display: flex; align-items: center; justify-content: center;
    cursor: pointer; flex-shrink: 0; font-size: 16px; transition: background 0.15s ease, transform 0.15s ease;
  }
  .gk-sidebar-toggle:hover { background: rgba(255,255,255,0.2); }
  .gk-mobile-hamburger { display: none; }
  .gk-mobile-backdrop { display: none; }
  /* SIDEBAR POSITION round: the sidebar can sit on the left (default) or
     right edge. It stays an in-flow column of the layout either way (the
     row is simply reversed), so it never overlays tables, forms or dialogs.
     The grip strip at the top is the ONLY place a drag can start. */
  .gk-shell[data-sidebar-side="right"] { flex-direction: row-reverse; }
  .gk-shell[data-sidebar-side="right"] .gk-sidebar { border-right: none; border-left: 1px solid rgba(255,255,255,0.06); }
  .gk-sidebar-grip {
    display: flex; align-items: center; justify-content: center; height: 16px; flex-shrink: 0;
    color: rgba(255,255,255,0.55); cursor: grab; touch-action: none; user-select: none;
    background: rgba(255,255,255,0.04); border-bottom: 1px solid rgba(255,255,255,0.08);
    transition: background 0.15s ease, color 0.15s ease;
  }
  .gk-sidebar-grip:hover, .gk-sidebar-grip:focus-visible { background: rgba(255,255,255,0.12); color: #fff; outline: none; }
  .gk-sidebar[data-dragging="true"] { transition: none !important; z-index: 300; box-shadow: 0 12px 40px rgba(8,20,30,0.35); opacity: 0.96; }
  .gk-sidebar[data-dragging="true"] .gk-sidebar-grip { cursor: grabbing; background: rgba(255,255,255,0.16); color: #fff; }
  .gk-sidebar-dropzone {
    position: fixed; top: 0; bottom: 0; width: 10px; z-index: 290; pointer-events: none;
    background: linear-gradient(180deg, var(--c-cyan), var(--c-navy)); opacity: 0.85;
    box-shadow: 0 0 22px color-mix(in srgb, var(--c-cyan) 60%, transparent);
    animation: gk-fade-in 0.15s ease;
  }
  .gk-sidebar-dropzone[data-side="left"] { left: 0; }
  .gk-sidebar-dropzone[data-side="right"] { right: 0; }
  .gk-sidebar-dropzone[data-side="top"], .gk-sidebar-dropzone[data-side="bottom"] { left: 0; right: 0; width: auto; height: 10px; bottom: auto; background: linear-gradient(90deg, var(--c-cyan), var(--c-navy)); }
  .gk-sidebar-dropzone[data-side="top"] { top: 0; }
  .gk-sidebar-dropzone[data-side="bottom"] { top: auto; bottom: 0; }
  /* SIDEBAR POSITION round 2: Top / Bottom turn the same menu into a
     horizontal bar (desktop only — phones keep the drawer). Groups become
     dropdowns (opening upward on the bottom bar). Same markup, routes and
     permissions; only layout changes. */
  @media (min-width: 769px) {
    .gk-shell[data-sidebar-side="top"] { flex-direction: column; }
    .gk-shell[data-sidebar-side="bottom"] { flex-direction: column-reverse; }
    .gk-sidebar[data-orient="h"] {
      width: auto !important; height: auto; flex-direction: row; align-items: stretch; align-self: stretch;
      overflow: visible; border-right: none; position: sticky; top: 0; z-index: 70;
      box-shadow: 0 2px 10px rgba(8,20,30,0.12);
    }
    .gk-sidebar[data-orient="h"][data-side="bottom"] { top: auto; bottom: 0; box-shadow: 0 -2px 10px rgba(8,20,30,0.12); }
    .gk-sidebar[data-orient="h"]::after { border-radius: 0; }
    .gk-sidebar[data-orient="h"] .gk-sidebar-grip { height: auto; width: 16px; border-bottom: none; border-right: 1px solid rgba(255,255,255,0.08); }
    .gk-sidebar[data-orient="h"] .gk-sidebar-grip svg { transform: rotate(90deg); }
    .gk-sidebar[data-orient="h"] .gk-sidebar-header { align-items: center !important; padding: 8px 14px !important; border-bottom: none !important; border-right: 1px solid rgba(255,255,255,0.12); flex-shrink: 0; max-width: 300px; }
    .gk-sidebar[data-orient="h"][data-collapsed="true"] .gk-sidebar-header { padding: 8px 10px !important; }
    .gk-sidebar[data-orient="h"] .gk-sidebar-nav { flex-direction: row !important; flex-wrap: wrap; align-items: center; overflow: visible !important; flex: 1; min-width: 0; padding: 6px 10px !important; gap: 4px !important; }
    .gk-sidebar[data-orient="h"] .gk-nav-group { position: relative; }
    .gk-sidebar[data-orient="h"] .gk-nav-btn { white-space: nowrap; width: auto !important; }
    .gk-sidebar[data-orient="h"] .gk-sidebar-nav > .gk-nav-btn, .gk-sidebar[data-orient="h"] .gk-nav-group-header { font-size: 13px !important; padding: 7px 8px !important; gap: 6px !important; }
    .gk-sidebar[data-orient="h"] .gk-nav-chevron { margin-left: 0; }
    /* The company name already shows in the Company switcher right next to
       the bar, so the bar's header keeps just the logo (name on hover). */
    .gk-sidebar[data-orient="h"] .gk-sidebar-header .gk-brand-text { display: none; }
    .gk-sidebar[data-orient="h"] .gk-sidebar-header { gap: 8px !important; }
    .gk-sidebar[data-orient="h"] .gk-sidebar-header .gk-sidebar-toggle { width: 28px; height: 28px; }
    .gk-sidebar[data-orient="h"] .gk-brand-logo-wrap { margin-top: 0 !important; }
    .gk-sidebar[data-orient="h"] .gk-nav-group-header { gap: 8px; }
    .gk-sidebar[data-orient="h"] .gk-nav-chevron { transform: rotate(90deg); margin-left: 2px; }
    .gk-sidebar[data-orient="h"] .gk-nav-chevron[data-open="true"] { transform: rotate(-90deg); }
    .gk-sidebar[data-orient="h"][data-side="bottom"] .gk-nav-chevron { transform: rotate(-90deg); }
    .gk-sidebar[data-orient="h"][data-side="bottom"] .gk-nav-chevron[data-open="true"] { transform: rotate(90deg); }
    .gk-sidebar[data-orient="h"] .gk-submenu {
      position: absolute; top: calc(100% + 6px); left: 0; min-width: 240px; z-index: 80;
      max-height: none !important; opacity: 1 !important; overflow: visible !important;
      background: linear-gradient(180deg, var(--c-navy-light) 0%, var(--c-navy) 60%, var(--c-navy-deep) 100%);
      border-radius: 10px; padding: 6px 8px 8px; box-shadow: 0 12px 32px rgba(8,20,30,0.30);
      border: 1px solid rgba(255,255,255,0.10);
    }
    .gk-sidebar[data-orient="h"][data-side="bottom"] .gk-submenu { top: auto; bottom: calc(100% + 6px); box-shadow: 0 -12px 32px rgba(8,20,30,0.30); }
    .gk-sidebar[data-orient="h"] .gk-submenu[data-open="false"] { display: none; }
    .gk-sidebar[data-orient="h"] .gk-nav-group:last-child .gk-submenu, .gk-sidebar[data-orient="h"] .gk-nav-group:nth-last-child(2) .gk-submenu { left: auto; right: 0; }
    .gk-sidebar[data-orient="h"] .gk-sidebar-footer { display: none; }
  }
  @media (min-width: 769px) and (max-width: 1399px) {
    .gk-sidebar[data-orient="h"] .gk-sidebar-nav { gap: 1px !important; padding: 6px 6px !important; }
    .gk-sidebar[data-orient="h"] .gk-sidebar-nav > .gk-nav-btn, .gk-sidebar[data-orient="h"] .gk-nav-group-header { padding: 7px 6px !important; gap: 4px !important; }
    .gk-sidebar[data-orient="h"] .gk-nav-chevron svg { width: 12px; height: 12px; }
  }
  .gk-side-seg { display: grid; grid-template-columns: 1fr 1fr; gap: 4px; padding: 0 14px 10px; }
  .gk-side-seg button { flex: 1; display: inline-flex; align-items: center; justify-content: center; gap: 5px; padding: 6px 0; font-size: 12px; font-weight: 600; border-radius: 6px; cursor: pointer; border: 1px solid var(--c-line); background: transparent; color: var(--c-slate); font-family: inherit; }
  .gk-side-seg button[aria-pressed="true"] { background: var(--c-navy); border-color: var(--c-navy); color: var(--c-text-on-primary, #fff); }

  @media (max-width: 768px) {
    .gk-sidebar {
      position: fixed; top: 0; left: 0; bottom: auto; width: 250px;
      height: calc(100vh / var(--c-zoom, 1)); height: calc(100dvh / var(--c-zoom, 1));
      transform: translateX(-100%); box-shadow: 6px 0 28px rgba(0,0,0,0.28);
      transition: transform 0.28s cubic-bezier(0.22,1,0.36,1);
    }
    .gk-sidebar[data-mobile-open="true"] { transform: translateX(0); }
    .gk-sidebar[data-collapsed="true"] { width: 250px; }
    .gk-sidebar[data-collapsed="true"] .gk-nav-label,
    .gk-sidebar[data-collapsed="true"] .gk-brand-text,
    .gk-sidebar[data-collapsed="true"] .gk-sidebar-footer-text { opacity: 1; max-width: none; transform: translateX(0); }
    .gk-sidebar[data-collapsed="true"] .gk-nav-btn { justify-content: flex-start; padding-left: 12px !important; padding-right: 12px !important; }
    .gk-sidebar-toggle.gk-desktop-only { display: none; }
    /* Phones keep the existing slide-in drawer from the left (opened by the
       hamburger, which sits top-left) — no dragging there. */
    .gk-sidebar-grip, .gk-sidebar-dropzone { display: none !important; }
    .gk-shell[data-sidebar-side="right"] .gk-sidebar { border-left: none; }
    .gk-mobile-hamburger { display: flex; }
    /* SYSTEM-WIDE ICON REDESIGN round: keep the company badge compact on phones. */
    .gk-company-badge-name { max-width: 96px !important; }
    .gk-topbar { padding: 10px 12px !important; }
    .gk-topbar-right { width: 100%; gap: 8px !important; }
    .gk-mobile-backdrop[data-visible="true"] {
      display: block; position: fixed; inset: 0; background: rgba(8,20,30,0.45); z-index: 55;
      animation: gk-fade-in 0.2s ease;
    }
  }
  @keyframes gk-fade-in { from { opacity: 0; } to { opacity: 1; } }
  /* LANGUAGE round: on tablets and phones the top bar wraps onto a second
     row, so the SO / EN switch, theme, notifications and profile all stay
     reachable instead of being pushed off the right edge. */
  @media (max-width: 1180px) {
    .gk-topbar { flex-wrap: wrap; row-gap: 8px !important; }
    .gk-topbar-left { flex-wrap: wrap; min-width: 0; }
    .gk-topbar-right { flex-wrap: wrap; justify-content: flex-end; margin-left: auto; }
  }

  /* --- ENTERPRISE FINANCIAL DASHBOARD round: chart entry animations --- */
  @keyframes gk-chart-fade-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
  .gk-chart-series { animation: gk-chart-fade-in 0.45s ease; }
  @keyframes gk-chart-grow { from { transform: scaleY(0); } to { transform: scaleY(1); } }
  .gk-chart-bar { animation: gk-chart-grow 0.35s ease; transform-origin: bottom; transition: opacity 0.15s ease; }
  .gk-widget-card { animation: gk-fade-in 0.25s ease; }

  /* =========================================================================
     COMPACT PREMIUM DASHBOARD round: presentation-only pass over the
     Dashboard page — layout, spacing, sizing, card design and density. Every
     rule below is scoped under .gk-dash (only the Dashboard's own root div
     carries that class) so nothing here touches any other module's tables,
     cards, buttons or charts. No data, calculations, permissions, routes or
     the Customize-Dashboard widget system are touched — this only restyles
     whatever widgets are already being rendered.
     ========================================================================= */
  .gk-dash .gk-dash-card {
    border-radius: 12px !important;
    padding: 16px !important;
    box-shadow: 0 1px 3px rgba(13,36,54,0.05);
    transition: box-shadow 180ms ease, transform 180ms ease;
  }
  .gk-dash .gk-dash-kpi-grid > div {
    border-radius: 12px !important;
    padding: 14px 16px !important;
    min-height: 106px;
    box-sizing: border-box;
    box-shadow: 0 1px 3px rgba(13,36,54,0.05) !important;
    border-color: color-mix(in srgb, var(--c-navy) 14%, var(--c-line)) !important;
    display: flex !important;
    flex-direction: column !important;
    justify-content: center !important;
    transition: transform 180ms ease, box-shadow 180ms ease;
  }
  .gk-dash .gk-dash-kpi-grid > div:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(13,36,54,0.09) !important;
  }
  .gk-dash-toolbar .gk-btn, .gk-dash-toolbar button { min-height: 36px; }
  .gk-dash-filterbar { border-radius: 12px !important; }
  /* Compact row density for the Dashboard's own list-style "tables"
     (Recent Transactions/Payments/Quotations/Exchanges, Top Accounts) —
     tighter row height/padding, matching spec item 14, without touching the
     shared .gk-table system used by every other module's real tables. */
  .gk-dash-row { padding: 7px 0 !important; }
  @media (max-width: 1100px) {
    .gk-dash-charts-2col, .gk-dash-lower-2col { grid-template-columns: 1fr !important; }
  }

  /* =========================================================================
     LOGIN SCREEN POLISH round: pure presentation — drifting background
     glows, a staggered fade-up entrance, a glowing focus ring on inputs, a
     password show/hide toggle, a shake on a failed attempt, and a spinning
     indicator on the submit button. No auth logic, field names, or routes
     are touched; everything here is scoped to .gk-login-* classes used only
     by LoginScreen.
     ========================================================================= */
  @keyframes gk-login-float {
    0%, 100% { transform: translate(0, 0) scale(1); }
    50% { transform: translate(2%, -3%) scale(1.06); }
  }
  .gk-login-blob { animation: gk-login-float 14s ease-in-out infinite; pointer-events: none; }
  @media (prefers-reduced-motion: reduce) { .gk-login-blob { animation: none; } }

  @keyframes gk-login-fade-up { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
  .gk-login-in { opacity: 0; animation: gk-login-fade-up 0.5s ease forwards; }
  @media (prefers-reduced-motion: reduce) { .gk-login-in { animation: none; opacity: 1; } }

  @keyframes gk-login-ring-pulse { 0%, 100% { box-shadow: 0 0 0 0 rgba(255,255,255,0.16); } 50% { box-shadow: 0 0 0 8px rgba(255,255,255,0); } }
  .gk-login-logo-ring { border-radius: 12px; animation: gk-login-ring-pulse 2.6s ease-in-out infinite; }

  .gk-login-card { transition: box-shadow 220ms ease, transform 220ms ease; box-shadow: 0 10px 40px rgba(0,0,0,0.18); }

  .gk-login-input-icon { position: absolute; left: 10px; top: 50%; transform: translateY(-50%); color: #5b7d8c; pointer-events: none; display: flex; transition: color 180ms ease; }
  .gk-login-input { transition: box-shadow 180ms ease, border-color 180ms ease, background 180ms ease; }
  .gk-login-input:focus { outline: none; border-color: ${C.cyan} !important; box-shadow: 0 0 0 3px color-mix(in srgb, ${C.cyan} 20%, transparent); background: #fff !important; }
  .gk-login-input-wrap[data-focused="true"] .gk-login-input-icon { color: ${C.navy}; }
  .gk-login-eye { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); background: none; border: none; padding: 4px; margin: 0; cursor: pointer; color: #5b7d8c; display: flex; align-items: center; justify-content: center; border-radius: 4px; transition: color 150ms ease, background 150ms ease; }
  .gk-login-eye:hover { color: ${C.navy}; background: rgba(0,0,0,0.05); }

  .gk-login-submit { width: 100%; transition: transform 150ms ease, box-shadow 150ms ease, filter 150ms ease; }
  .gk-login-submit:hover:not(:disabled) { box-shadow: 0 6px 18px rgba(0,0,0,0.22); }
  .gk-login-submit:active:not(:disabled) { transform: translateY(0) scale(0.99); }

  @keyframes gk-login-shake { 0%, 100% { transform: translateX(0); } 20% { transform: translateX(-4px); } 40% { transform: translateX(4px); } 60% { transform: translateX(-3px); } 80% { transform: translateX(3px); } }
  .gk-login-error { animation: gk-login-shake 0.4s ease; }

  /* EXCHANGE WORKSPACE round: the New/Edit Exchange Transaction surface
     moved from a small centered Modal card to a dedicated full-screen page
     (spec: "premium full-screen financial exchange workspace"). Two-column
     desktop layout collapses to one column at 980px, and the Given/Received
     panel pair (plus the Cash Out/Cash In pair) stacks at 640px — the exact
     same "desktop two-column, mobile single-column, no horizontal overflow"
     contract every other redesigned surface in this app already follows. */
  .gk-exw-grid { display: grid; grid-template-columns: 1fr 360px; gap: 22px; align-items: start; }
  @media (max-width: 980px) { .gk-exw-grid { grid-template-columns: 1fr; } }
  .gk-exw-pair { display: grid; grid-template-columns: 1fr auto 1fr; gap: 14px; align-items: center; }
  @media (max-width: 640px) { .gk-exw-pair { grid-template-columns: 1fr; } .gk-exw-pair-arrow { transform: rotate(90deg); margin: 0 auto; } }
  .gk-exw-cashpair { display: grid; grid-template-columns: 1fr auto 1fr; gap: 14px; align-items: center; }
  @media (max-width: 640px) { .gk-exw-cashpair { grid-template-columns: 1fr; } .gk-exw-cashpair-arrow { transform: rotate(90deg); margin: 0 auto; } }
  @media (max-width: 640px) { .gk-exw-profitdate { grid-template-columns: 1fr !important; } }
  /* QUICK EXCHANGE round */
  .gk-qx-header { display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; }
  .gk-qx-dir { display: grid; grid-template-columns: 1fr auto 1fr; gap: 12px; align-items: center; }
  .gk-qx-rategrid { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.3fr); gap: 14px; align-items: start; }
  .gk-qx-ratetiles { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
  .gk-qx-tile { border: 1px solid ${C.line}; border-radius: 9px; padding: 8px 10px; display: flex; flex-direction: column; gap: 4px; min-width: 0; }
  .gk-qx-tile span { display: flex; align-items: center; gap: 5px; font-size: 10.5px; font-weight: 600; color: ${C.slate}; }
  .gk-qx-tile b { font-family: "JetBrains Mono", "SFMono-Regular", Menlo, monospace; font-size: 14px; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
  .gk-qx-results { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
  .gk-qx-chip:hover, .gk-qx-ghost:hover, .gk-qx-curcard:hover:not(:disabled) { border-color: var(--c-navy) !important; }
  .gk-qx-swap:hover:not(:disabled) { background: var(--c-navy) !important; color: #fff !important; }
  .gk-qx button:focus-visible, .gk-qx [tabindex]:focus-visible { outline: 2px solid var(--c-navy); outline-offset: 2px; }
  @media (max-width: 980px) { .gk-qx-summary { position: static !important; } }
  @media (max-width: 760px) { .gk-qx-rategrid, .gk-qx-results { grid-template-columns: 1fr; } }
  @media (max-width: 520px) { .gk-qx-dir { grid-template-columns: 1fr; } .gk-qx-swap { transform: rotate(90deg); } .gk-qx-ratetiles { grid-template-columns: 1fr 1fr; } }
  /* Direction toggle: a two-segment pill switch, the "[ USD ] ⇄ [ SLSH ]"
     selector from the spec. Clicking either segment (or the arrow) swaps
     currencyGiven, reusing the existing swapCurrencies() logic untouched. */
  .gk-exw-dir-btn { transition: background-color 150ms ease, color 150ms ease, box-shadow 150ms ease; }
  .gk-exw-dir-swap { transition: transform 220ms cubic-bezier(0.4,0,0.2,1), background-color 150ms ease; }
  .gk-exw-dir-swap:hover { background: color-mix(in srgb, var(--c-navy) 10%, transparent) !important; }
  .gk-exw-dir-swap:active { transform: rotate(180deg); }
  /* Micro-interaction: any live-recalculated value (converted amount,
     profit, cash balances) briefly flashes its tinted background when it
     changes, via a key-remount — subtle, fast, never a bounce (spec #18). */
  @keyframes gk-exw-flash { from { background-color: color-mix(in srgb, var(--c-navy-light) 16%, transparent); } to { background-color: transparent; } }
  .gk-exw-flash { animation: gk-exw-flash 420ms ease-out; }
  .gk-exw-card { transition: border-color 150ms ease, box-shadow 150ms ease; }
  .gk-exw-card:focus-within { border-color: var(--c-navy-light) !important; box-shadow: 0 0 0 3px color-mix(in srgb, var(--c-navy-light) 15%, transparent); }
  .gk-exw-save-btn { transition: transform 150ms ease, box-shadow 150ms ease, filter 150ms ease; }
  .gk-exw-save-btn:hover:not(:disabled) { filter: brightness(1.06); box-shadow: 0 6px 18px color-mix(in srgb, var(--c-navy) 28%, transparent); }
  .gk-exw-save-btn:active:not(:disabled) { transform: scale(0.99); }
  .gk-exw-back:hover { background: rgba(0,0,0,0.05) !important; }
  .gk-exw-back.gk-btn-back-outline:hover:not(:disabled) { background: var(--c-back-tint) !important; }
  /* GLOBAL HEADER REDESIGN (Option 3 — Compact Unified Header) */
  .gk-ph { margin-bottom: 10px; }
  .gk-ph-row { display: flex; align-items: center; justify-content: space-between; gap: 8px 12px; flex-wrap: wrap; min-height: 40px; }
  .gk-ph-head { display: flex; align-items: center; gap: 10px; min-width: 0; flex: 1 1 260px; }
  .gk-ph-icon { width: 30px; height: 30px; border-radius: 8px; display: inline-flex; align-items: center; justify-content: center; background: color-mix(in srgb, var(--c-navy) 12%, transparent); color: var(--c-navy); flex-shrink: 0; }
  .gk-ph-text { min-width: 0; }
  .gk-ph-title { margin: 0; font-size: 17px; line-height: 1.25; font-weight: 700; color: var(--c-ink); letter-spacing: -0.01em; overflow-wrap: anywhere; }
  .gk-ph-sub { font-size: 11.5px; line-height: 1.35; color: var(--c-slate); margin-top: 1px; display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden; }
  .gk-ph-actions { display: flex; align-items: center; justify-content: flex-end; gap: 6px; flex-wrap: wrap; }
  .gk-ph-tabs { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 8px; }
  .gk-ph-tab { background: none; border: 1px solid var(--c-line); color: var(--c-slate); font: inherit; font-size: 12px; font-weight: 600; padding: 5px 11px; border-radius: 5px; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; }
  .gk-ph-tab.is-active { background: var(--c-navy); border-color: var(--c-navy); color: var(--c-text-on-primary); }
  .gk-ph-tab:focus-visible, .gk-om-btn:focus-visible, .gk-om-item:focus-visible { outline: 2px solid var(--c-cyan); outline-offset: 1px; }
  .gk-tabbar { display: flex; gap: 6px; flex-wrap: wrap; margin: 0 0 10px; }
  .gk-om-wrap { position: relative; display: inline-flex; }
  .gk-om-btn { width: 34px; height: 32px; display: inline-flex; align-items: center; justify-content: center; border: 1px solid var(--c-line); border-radius: 6px; background: var(--c-card); color: var(--c-navy); cursor: pointer; }
  .gk-om-btn:hover, .gk-om-btn[aria-expanded="true"] { background: color-mix(in srgb, var(--c-navy) 10%, var(--c-card)); }
  .gk-om { position: absolute; top: calc(100% + 4px); right: 0; z-index: 300; min-width: 220px; max-width: min(300px, calc(100vw - 24px)); max-height: 65vh; overflow: auto; background: var(--c-card); border: 1px solid var(--c-line); border-radius: 8px; box-shadow: 0 12px 32px rgba(8,20,30,0.18); padding: 4px; }
  .gk-om--left { right: auto; left: 0; }
  .gk-om-group + .gk-om-group { border-top: 1px solid var(--c-line); margin-top: 4px; padding-top: 4px; }
  .gk-om-heading { font-size: 10.5px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; color: var(--c-slate); padding: 6px 10px 3px; }
  .gk-om-item { width: 100%; display: flex; align-items: center; gap: 9px; text-align: left; background: none; border: 0; border-radius: 5px; padding: 7px 10px; font: inherit; font-size: 12.5px; color: var(--c-ink); cursor: pointer; }
  .gk-om-item:hover:not(:disabled), .gk-om-item:focus { background: color-mix(in srgb, var(--c-navy) 9%, transparent); }
  .gk-om-item:disabled { opacity: 0.5; cursor: not-allowed; }
  .gk-om-icon { width: 16px; display: inline-flex; color: var(--c-navy); }
  /* Compact, consistent search/filter bars */
  .gk-filterbar { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 8px 10px; margin-bottom: 10px; background: var(--c-card); border: 1px solid var(--c-line); border-radius: 6px; padding: 8px 10px; }
  .gk-filterbar--inset { background: var(--c-paper); margin-bottom: 8px; }
  .gk-filterbar input:not([type="checkbox"]):not([type="radio"]), .gk-filterbar select { min-height: 30px; }
  @media (max-width: 640px) {
    .gk-ph-head { flex-basis: 100%; }
    .gk-ph-actions { justify-content: flex-start; width: 100%; }
    .gk-ph-sub { -webkit-line-clamp: 2; }
    .gk-filterbar > * { flex: 1 1 140px; }
  }

`;
// APPEARANCE & BRANDING round 2: FONT_SANS now reads the CSS variable
// (defaulting to the original Inter stack in THEME_CSS's :root block) so
// every one of the ~20 inline `fontFamily: FONT_SANS` usages throughout this
// file picks up a Super Admin's chosen Font Family automatically, with no
// per-component changes needed.
const FONT_SANS = "var(--c-font-family)";
const FONT_MONO = '"JetBrains Mono", "SFMono-Regular", Menlo, monospace';
// GLOBAL LOGIN round: the platform's own neutral identity — what the shared
// login page shows. It is never a particular company's name or description.
const COMPANY = { name: "OBO Financial System", tagline: "Multi-company financial management" };

// APPEARANCE & BRANDING round 2: Font Family and Font Size are each a
// curated set of keys (matching settings.js's FONT_FAMILY_KEYS/FONT_SIZE_KEYS
// whitelist) rather than free-form CSS/px input, so a bad value can never
// break layout. Font Size is applied as a CSS `zoom` on <html> — the
// simplest way to scale an app built on fixed px sizes throughout without a
// much larger rem-based refactor; it's a Chromium-supported property, which
// covers this app's actual runtime (the Electron-based desktop shell / any
// Chromium-family browser it's opened in).
// POPPINS TABLE DESIGN round: Poppins replaces Inter as the system's default
// typeface (spec: "Poppins — Modern & Elegant", applied system-wide for
// consistency — section 19 explicitly asks every table to share one
// typography, and FONT_SANS/--c-font-family already drives the whole app,
// not just tables). "poppins" is now the sentinel that means "use THEME_CSS's
// own default" (see the effect below) — "inter" becomes an ordinary,
// explicitly-applied alternative like every other option, so an install that
// already saved fontFamily:"inter" keeps rendering in Inter unchanged.
const FONT_FAMILY_OPTIONS = [
  { key: "poppins", label: "Poppins (default)", stack: '"Poppins", "Segoe UI", Arial, sans-serif' },
  { key: "inter", label: "Inter", stack: '"Inter", "Segoe UI", Arial, sans-serif' },
  { key: "system", label: "System UI", stack: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif' },
  { key: "georgia", label: "Georgia (serif)", stack: 'Georgia, "Times New Roman", serif' },
  { key: "times", label: "Times New Roman (serif)", stack: '"Times New Roman", Times, serif' },
  { key: "verdana", label: "Verdana", stack: 'Verdana, Geneva, Arial, sans-serif' },
  { key: "courier", label: "Courier New (mono)", stack: '"Courier New", Courier, monospace' },
];
const FONT_SIZE_OPTIONS = [
  { key: "small", label: "Small", zoom: 0.925 },
  { key: "medium", label: "Medium (default)", zoom: 1 },
  { key: "large", label: "Large", zoom: 1.075 },
];
// APPEARANCE & BRANDING round 2: Theme Presets are a pure frontend
// convenience — each one just fills in the Brand/Secondary/Accent Color
// fields below with a curated, contrast-checked combo. There's no separate
// "presets" table or API: picking one only stages the three color fields
// (the Super Admin still presses Save to persist, exactly as if they'd
// picked each color by hand), and "Geeska Default" clears all three back to
// null so an uncustomized install's original hex values apply again.
// BRAND COLOR MANAGEMENT round: the 5 exact, professionally-designed brand
// themes (spec section 2 — do not rename, do not alter the hex values).
// Each theme's 6 colors map onto the app's existing 3 stored+derived color
// slots exactly as the rest of the UI already reads them: primary ->
// brandColor (C.navy — sidebar/buttons/links/login), accent -> accentColor
// (C.cyan — active submenu/focus rings/badges), softAccent -> secondaryColor
// (C.mint — subtle highlights). primaryDark/primaryLight/accentBright are
// new, explicit fields (see db.js/routes/settings.js) so each theme's exact
// look survives a save instead of being re-derived by lightness shift.
const BRAND_THEMES = [
  {
    key: "emerald-finance", label: "Emerald Finance", isDefault: true,
    description: "Premium · Financial · Modern · Secure · Exchange / Banking",
    primary: "#005F4B", primaryDark: "#004C3D", primaryLight: "#008E6D",
    accent: "#00B98A", accentBright: "#00D7A0", softAccent: "#C6FBEA", textOnPrimary: "#FFFFFF",
  },
  {
    key: "ocean-blue", label: "Ocean Blue",
    description: "Professional · Corporate · Banking · Technology",
    primary: "#075985", primaryDark: "#053B5C", primaryLight: "#0EA5E9",
    accent: "#38BDF8", accentBright: "#67E8F9", softAccent: "#BAE6FD", textOnPrimary: "#FFFFFF",
  },
  {
    key: "royal-purple", label: "Royal Purple",
    description: "Premium · Executive · Modern · Luxury",
    primary: "#5B21B6", primaryDark: "#3B1478", primaryLight: "#7C3AED",
    accent: "#A78BFA", accentBright: "#C4B5FD", softAccent: "#EDE9FE", textOnPrimary: "#FFFFFF",
  },
  {
    key: "midnight-teal", label: "Midnight Teal",
    description: "Elegant · Dark · Professional · Financial",
    primary: "#134E4A", primaryDark: "#0F3633", primaryLight: "#0F766E",
    accent: "#14B8A6", accentBright: "#2DD4BF", softAccent: "#99F6E4", textOnPrimary: "#FFFFFF",
  },
  {
    key: "ruby-red", label: "Ruby Red",
    description: "Executive · Strong · Corporate · Premium",
    primary: "#991B1B", primaryDark: "#641313", primaryLight: "#B91C1C",
    accent: "#EF4444", accentBright: "#F87171", softAccent: "#FECACA", textOnPrimary: "#FFFFFF",
  },
];
const DEFAULT_BRAND_THEME = BRAND_THEMES.find((t) => t.isDefault) || BRAND_THEMES[0];

// Legacy display-only fallback (used for the plain "New User" role picker
// and historical Audit Log rows, which only ever stored this flat string) —
// no longer the source of truth for what a user can actually DO. A logged-in
// user's REAL display role now comes from the server as user.roleLabel (see
// SUPER ADMIN + ADVANCED ROLE & PERMISSION MANAGEMENT round, Phase 3, below).
const ROLE_LABELS = { admin: "Admin", manager: "Manager", accountant: "Accountant", cashier: "Cashier / Teller", sales: "Sales Staff", viewer: "Viewer / Auditor" };
// SUPER ADMIN + ADVANCED ROLE & PERMISSION MANAGEMENT round, Phase 3: the
// hard-coded PERMS table (and the can(role, key) it fed) that used to decide
// every menu/button in this file is gone. Every one of the ~59 perm("...")
// call sites below is unchanged — same legacy key names (accountsManage,
// reports, quotationsManage, etc.) — but `perm` itself (defined inside App())
// now simply reads user.perms, a snapshot the SERVER resolves through the
// real, DB-backed, Super-Admin-aware granular permission engine (src/
// rbac.js's resolvedPermsPayload, delivered on every login and /api/auth/me
// call) instead of this static table. quotationsDelete/exchangeDelete/
// exchangeUpdate/etc. still mean exactly what their names say (see
// LEGACY_KEY_MAP in src/permissions.js for the authoritative, commented
// mapping of each legacy key to what it really gates).
// TWO-STEP ACCOUNT LEDGER LOGIC: a quotation's status is now just
// Pending (charged, awaiting settlement) -> Paid or Refunded.
// APPEARANCE & BRANDING round 2: each status color is now its own CSS
// variable (independent of C.amber/C.green/C.cyan, which stay fixed) so a
// Super Admin can recolor Pending/Paid/Refunded without touching unrelated
// UI that happens to reuse those same base tokens (e.g. C.cyan's Btn
