// hex values exactly, so an uncustomized install looks unchanged.
const STATUS_COLORS = { Pending: "var(--c-status-pending)", Paid: "var(--c-status-paid)", Refunded: "var(--c-status-refunded)" };

/* ---------------- formatting ---------------- */
function fmtDate(s) { if (!s) return "—"; const d = s.length === 10 ? new Date(s + "T00:00:00") : new Date(s); return d.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" }); }
function fmtDateTime(s) { if (!s) return "—"; return new Date(s).toLocaleString("en-GB", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" }); }
// ACCOUNT VIEW TRANSACTION TABLE round: Account View's Transactions tab
// needs the exact Date + Time + Seconds a row sorts by to be visible, not
// just the day (see fmtDate above) — otherwise same-day rows that are
// genuinely in a different order (per the server's chronoSortKey, which
// already sorts by the full timestamp) look arbitrarily shuffled to anyone
// reading the table, even though the order is correct. Returns the time
// portion only (HH:MM:SS, 24h) for pairing under the date in a cell — the
// date itself keeps using fmtDate so its format/weight stays exactly as
// before. A day-only `date` (no time ever recorded) returns null so the
// caller can skip showing a fake "00:00:00".
function fmtTimeSeconds(s) {
  if (!s || String(s).length <= 10) return null;
  const d = new Date(s);
  if (Number.isNaN(d.getTime())) return null;
  return d.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false });
}
// ALL-TABLES DATE+TIME round: same Date+Time cell the Account View
// Transactions table got, pulled into one shared component so every other
// table's date column renders it identically instead of re-typing the
// two-line markup — date on top (fmtDate, unchanged weight/format), the
// exact time in small muted monospace underneath ONLY when the stored
// value actually carries a time (fmtTimeSeconds returns null for a bare
// day-only date, e.g. "Valid until" deadlines or day-rollup keys, so those
// correctly keep showing just the date with no fabricated "00:00:00").
function DateTimeCell({ value }) {
  const t = fmtTimeSeconds(value);
  return (
    <>
      <div>{fmtDate(value)}</div>
      {t && <div style={{ fontSize: 10.5, color: C.slate, fontFamily: FONT_MONO, marginTop: 1 }}>{t}</div>}
    </>
  );
}
function fmtMoney(amount, currency) {
  const n = Number(amount) || 0;
  const neg = n < 0; const abs = Math.abs(n);
  const body = currency === "USD" ? `$${abs.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : `SLSH ${Math.round(abs).toLocaleString("en-US")}`;
  return neg ? `-${body}` : body;
}
function fmtNum(n) { return Number(n || 0).toLocaleString("en-US"); }
// GLOBAL RATE & PROFIT round: "+SLSH 20,000" / "−SLSH 5,000" / "SLSH 0".
function fmtSignedUsd(n) {
  const v = Math.round(Number(n || 0) * 100) / 100;
  const abs = Math.abs(v).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return v > 0 ? `+$${abs}` : v < 0 ? `−$${abs}` : "$0.00";
}
function fmtSignedSlsh(n) {
  const v = Math.round(Number(n || 0) * 100) / 100;
  const abs = Math.abs(v).toLocaleString("en-US", { maximumFractionDigits: 2 });
  return v > 0 ? `+SLSH ${abs}` : v < 0 ? `−SLSH ${abs}` : "SLSH 0";
}
// GLOBAL ACCOUNT NAME FORMATTING round: display-only Title Case formatter
// for customer/company/account names. Stored names stay exactly as entered
// (formatPersonName above still UPPERCASEs on save — that is unchanged and
// is what every search/match/sort/API call continues to compare against).
// This function ONLY changes what is rendered on screen.
// Rule (reverse-engineered from the spec's own examples so punctuation is
// preserved correctly): split on spaces only. Within each space-separated
// word, capitalize the first letter AND any letter immediately following a
// hyphen (so "A-RAHEEN" -> "A-Raheen"); lowercase everything else,
// including letters after an apostrophe or slash (so "MOH'ED" -> "Moh'ed"
// and "C/LAAHI" -> "C/laahi", matching the spec's own worked examples).
