// BRAND COLOR MANAGEMENT round: WCAG-ish relative luminance, used to pick a
// readable text color (white vs. dark ink) for any surface tinted with a
// brand/accent color — the 5 built-in themes always specify white (they're
// all dark/mid-tone enough), but a Custom Brand Color could be anything
// (including something very light), so this is computed rather than assumed.
function relLuminance(hex) {
  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || "").trim());
  if (!m) return 0;
  const int = parseInt(m[1], 16);
  const chan = (c) => { c /= 255; return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4); };
  const r = chan((int >> 16) & 255), g = chan((int >> 8) & 255), b = chan(int & 255);
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
