/* ---------------- API client ---------------- */
const TOKEN_KEY = "geeska_token", USER_KEY = "geeska_user";

/* ---------------- SOMALI / ENGLISH LANGUAGE ----------------
   The chosen language is kept in this browser (obo_lang) so it survives a
   refresh, signing out and in, and switching company. Interface text is
   translated by the JSX runtime (frontend/i18n-jsx) through src/i18n; the
   server is told the language on every request (X-Lang) so its messages
   and exported documents follow it too. */
const LANG_KEY = "obo_lang";
function readSavedLang() { try { return localStorage.getItem(LANG_KEY) === "so" ? "so" : "en"; } catch (e) { return "en"; } }
setI18nLang(readSavedLang());
const LangContext = createContext({ lang: "en", setLang: () => {} });
// GLOBAL RATE & PROFIT round: the company's Cost / Buy / Sell rates (SLSH per
// 1 USD), loaded once by App and shared with every screen that shows a
// margin; setRates() is called after Manage Rates saves.
const RatesContext = createContext({ costRate: null, buyRate: null, sellRate: null, setRates: () => {} });
// Native dialogs don't go through React — translate their text here.
{
  const nativeConfirm = window.confirm.bind(window), nativeAlert = window.alert.bind(window);
  window.confirm = (m) => nativeConfirm(translate(m));
  window.alert = (m) => nativeAlert(translate(m));
}
// For testing: the strings shown in Somali mode that have no translation yet.
window.__i18n = { missing: i18nMissing, translate, getLang };
function authHeaders(token) {
  const h = { "X-Lang": getLang() };
  if (token) h.Authorization = `Bearer ${token}`;
  return h;
}
// SO | EN switch — same compact rounded pill as the theme switch.
function LangToggle({ onDark }) {
  const { lang, setLang } = useContext(LangContext);
  const btn = (code, label, title) => (
    <button key={code} type="button" onClick={() => setLang(code)} aria-pressed={lang === code} title={title} aria-label={title}
      data-no-i18n="1"
      style={{ minWidth: 34, height: 28, padding: "0 9px", borderRadius: 14, border: "none", cursor: "pointer", fontFamily: FONT_SANS, fontSize: 12, fontWeight: 800, letterSpacing: "0.04em",
        background: lang === code ? (onDark ? "#fff" : C.navy) : "transparent",
        color: lang === code ? (onDark ? C.navyDeep : "var(--c-text-on-primary)") : (onDark ? "rgba(255,255,255,0.85)" : C.slate),
        transition: "background 0.15s ease, color 0.15s ease" }}>
      {label}
    </button>
  );
  return (
    <div role="group" aria-label="Language / Luqadda" className="gk-lang-toggle" data-no-i18n="1"
      style={{ display: "inline-flex", background: onDark ? "rgba(255,255,255,0.14)" : C.slateBg, borderRadius: 20, padding: 3, gap: 2, flexShrink: 0 }}>
      {btn("so", "SO", "Af-Soomaali")}
      {btn("en", "EN", "English")}
    </div>
  );
}

async function api(path, { method = "GET", body } = {}, token) {
  const headers = authHeaders(token);
  // SECURITY & INTEGRITY AUDIT round: a form's one-per-submission id travels
  // as the Idempotency-Key header (src/idempotency.js), never in the body, so
  // a repeated or retried save is answered once and never posted twice.
  if (body && typeof body === "object" && !Array.isArray(body) && typeof body._requestId === "string") {
    const { _requestId, ...rest } = body;
    headers["Idempotency-Key"] = _requestId;
    body = rest;
  }
  if (body !== undefined) headers["Content-Type"] = "application/json";
  const res = await fetch(path, { method, headers, body: body !== undefined ? JSON.stringify(body) : undefined });
  const text = await res.text();
  let data = null;
  try { data = text ? JSON.parse(text) : null; } catch (e) { /* non-JSON response */ }
  if (!res.ok) {
    const err = new Error((data && data.error) || `Request failed (${res.status})`);
    err.status = res.status;
    // BULK TRANSACTION WORKSPACE round: callers that need more than the flat
    // message string (e.g. the bulk-save endpoint's per-item `itemErrors`
    // array) can read `e.data` for the full parsed JSON body. Every existing
    // caller only ever reads `e.message`/`e.status`, so this is purely
    // additive and changes nothing for them.
    err.data = data;
    throw err;
  }
  return data;
}
async function downloadFile(path, filename, token) {
  const res = await fetch(path, { headers: authHeaders(token) });
  if (!res.ok) {
    let msg = `Export failed (${res.status})`;
    try { const j = await res.json(); if (j.error) msg = j.error; } catch (e) { /* ignore */ }
    throw new Error(msg);
  }
  const blob = await res.blob();
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 5000);
}
// PROFESSIONAL ACCOUNT REPORTS round: same authenticated-fetch shape as
// downloadFile() above, but opens the result in a new tab instead of
// triggering a save-as — used for the Account Statement's "Preview PDF"
// button (spec: see the actual selected account's data before exporting).
async function previewFile(path, token) {
  const res = await fetch(path, { headers: authHeaders(token) });
  if (!res.ok) {
    let msg = `Preview failed (${res.status})`;
    try { const j = await res.json(); if (j.error) msg = j.error; } catch (e) { /* ignore */ }
    throw new Error(msg);
  }
  const blob = await res.blob();
  const url = URL.createObjectURL(blob);
  window.open(url, "_blank");
  setTimeout(() => URL.revokeObjectURL(url), 60000);
}
// MASTER PROMPT — the third leg of the unified Preview/Export PDF/Export
// Excel/Print button set: opens the same authenticated PDF in a new tab
// (same fetch-as-blob shape as previewFile above) and, once the browser has
// actually rendered it, triggers that tab's own native print dialog — so
// "Print" always prints the real, current document rather than whatever the
// main app window happens to be showing.
async function printFile(path, token) {
  const res = await fetch(path, { headers: authHeaders(token) });
  if (!res.ok) {
    let msg = `Print failed (${res.status})`;
    try { const j = await res.json(); if (j.error) msg = j.error; } catch (e) { /* ignore */ }
    throw new Error(msg);
  }
  const blob = await res.blob();
  const url = URL.createObjectURL(blob);
  const win = window.open(url, "_blank");
  if (win) {
    const tryPrint = () => { try { win.focus(); win.print(); } catch (e) { /* popup blocked or already closed */ } };
    win.addEventListener("load", tryPrint);
    setTimeout(tryPrint, 800); // fallback for browsers that don't fire load on a PDF viewer tab
  }
  setTimeout(() => URL.revokeObjectURL(url), 60000);
}
// PDF TEMPLATE & CUSTOMIZATION ENGINE round: the settings-panel customizer's
// live preview needs the fetched PDF's blob URL back (to embed inline in an
// <iframe>), not opened in a new tab (previewFile) or saved to disk
// (downloadFile) — same authenticated-fetch shape as both, one more variant.
async function fetchBlobUrl(path, token) {
  const res = await fetch(path, { headers: authHeaders(token) });
  if (!res.ok) {
    let msg = `Preview failed (${res.status})`;
    try { const j = await res.json(); if (j.error) msg = j.error; } catch (e) { /* ignore */ }
    throw new Error(msg);
  }
  const blob = await res.blob();
  return URL.createObjectURL(blob);
}
function qs(params) {
  const p = new URLSearchParams();
  Object.entries(params || {}).forEach(([k, v]) => { if (v !== undefined && v !== null && v !== "" && v !== "all") p.set(k, v); });
  const s = p.toString();
  return s ? `?${s}` : "";
}

