function CashExchangeFormModal({ accounts, rate, onClose, onSubmit }) {
  // SECURITY & INTEGRITY AUDIT round: one id per opening of this form — a
  // double click or retried save is answered once, never posted twice.
  const [_requestId] = useState(() => newRequestId());
  const [fromId, setFromId] = useState("");
  const [toId, setToId] = useState("");
  const [amountGiven, setAmountGiven] = useState("");
  const [date, setDate] = useState(todayStr());
  const [notes, setNotes] = useState("");
  const [saving, setSaving] = useState(false);
  // CASH EXCHANGE RATE OVERRIDE round: this follows the live Cash in Hand
  // rate by default (same `rate` the "Current rate" line always showed),
  // but can now be edited per-transaction — mirrors the Money Exchange
  // module's own Rate field (AddTxModal's rateUsed), and the backend
  // already accepts this override via body.rateUsed (see routes/cash.js's
  // POST /api/cash/exchanges — unchanged, this just exposes it in the UI).
  const [rateUsed, setRateUsed] = useState("");
  const effectiveRate = rateUsed !== "" ? Number(rateUsed) : rate;
  const fromAcc = accounts.find((a) => a.id === fromId);
  const oppositeTargets = accounts.filter((a) => a.id !== fromId && (!fromAcc || a.currency !== fromAcc.currency));
  const toAcc = accounts.find((a) => a.id === toId);
  const estimatedReceived = fromAcc && toAcc && effectiveRate && Number(amountGiven) ? convertPreview(Number(amountGiven), fromAcc.currency, toAcc.currency, effectiveRate) : null;
  function convertPreview(n, from, to, r) { return to === "USD" ? n / r : n * r; }
  async function submit() {
    if (!fromId || !toId || !Number(amountGiven)) return;
    setSaving(true);
    try { await onSubmit({ _requestId, fromCashAccountId: fromId, toCashAccountId: toId, amountGiven: Number(amountGiven), date, notes: notes.trim() || undefined, rateUsed: rateUsed === "" ? undefined : Number(rateUsed) }); }
    finally { setSaving(false); }
  }
  return (
    <Modal title="Exchange Between Cash Accounts" onClose={onClose}>
      <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, border: `1px solid ${C.green}`, background: C.greenBg, borderRadius: 7, padding: "10px 12px" }}>
          <div style={{ fontSize: 12, color: C.navyDeep }}>Current rate: <span style={{ fontFamily: FONT_MONO, fontWeight: 700, color: C.ink }}>{rate ? `1 USD = SLSH ${fmtNum(rate)}` : "not set"}</span></div>
          <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
            <span style={{ fontSize: 10, fontWeight: 700, color: C.green, textTransform: "uppercase" }}>Rate</span>
            <MoneyInput placeholder={rate ? String(rate) : "—"} value={rateUsed} onChange={(e) => setRateUsed(e.target.value)} aria-label="Rate" style={{ width: 90, textAlign: "center", fontFamily: FONT_MONO, fontSize: 13, padding: "5px 4px", background: C.card }} />
          </div>
        </div>
        <Field label="From (USD or SLSH account)"><Select value={fromId} onChange={(e) => { setFromId(e.target.value); setToId(""); }}>
          <option value="">Select source account…</option>
          {accounts.map((a) => <option key={a.id} value={a.id}>{toTitleCase(a.name)} ({a.currency}) — {fmtMoney(a.balance, a.currency)}</option>)}
        </Select></Field>
        <Field label="To (opposite currency account)"><Select value={toId} onChange={(e) => setToId(e.target.value)} disabled={!fromId}>
          <option value="">Select destination account…</option>
          {oppositeTargets.map((a) => <option key={a.id} value={a.id}>{toTitleCase(a.name)} ({a.currency}) — {fmtMoney(a.balance, a.currency)}</option>)}
        </Select></Field>
        <Field label={`Amount Given${fromAcc ? ` (${fromAcc.currency})` : ""}`}><MoneyInput value={amountGiven} onChange={(e) => setAmountGiven(e.target.value)} /></Field>
        {estimatedReceived != null && <div style={{ fontSize: 12.5, color: C.slate }}>Estimated received at {rateUsed !== "" ? "the rate above" : "current rate"}: <span style={{ fontFamily: FONT_MONO, fontWeight: 700, color: C.ink }}>{fmtMoney(estimatedReceived, toAcc.currency)}</span></div>}
        <Field label="Date"><Input type="date" value={date} onChange={(e) => setDate(e.target.value)} /></Field>
        <OptionalNotes value={notes} onChange={(e) => setNotes(e.target.value)} multiline={false} />
      </div>
      <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 18 }}>
        <Btn tone="ghost" onClick={onClose}>Cancel</Btn>
        <Btn tone="accent" onClick={submit} disabled={saving || !fromId || !toId || !Number(amountGiven)}>{saving ? "Saving…" : "Exchange"}</Btn>
      </div>
    </Modal>
  );
}

