// CASH IN HAND — INDEPENDENT RATE round: a small, dedicated "Edit Rate"
// modal for Cash in Hand's own exchange rate — deliberately NOT the
// header's ManageRatesModal (which edits the separate, company-wide
// Daily+Sale Rate in rate_history). Saves via POST /api/cash/rate, which
// writes to cash_rate_history (see domain.js's saveCashRateHistory()) and
// never touches rate_history.
function CashRateEditModal({ call, notify, rate, onSaved, onClose }) {
  const [rateVal, setRateVal] = useState(rate ? String(rate) : "");
  const [note, setNote] = useState("");
  const [saving, setSaving] = useState(false);
  async function submit() {
    if (!Number(rateVal) || Number(rateVal) <= 0) return notify("Provide a positive Rate.", true);
    setSaving(true);
    try {
      await call("/api/cash/rate", { method: "POST", body: { rate: Number(rateVal), note: note.trim() || undefined } });
      notify("Cash Account rate updated.");
      onSaved();
    } catch (e) { notify(e.message, true); } finally { setSaving(false); }
  }
  return (
    <Modal title="Edit Cash Account Rate" onClose={onClose}>
      <div style={{ fontSize: 12, color: C.slate, marginBottom: 14 }}>Used for Cash Account's own Cash Exchanges and Net Cash Account conversion — separate from the company-wide Daily/Sale Rate used elsewhere in the system.</div>
      <Field label="Rate (SLSH per 1 USD)" width={210}><MoneyInput autoFocus value={rateVal} onChange={(e) => setRateVal(e.target.value)} /></Field>
      <div style={{ marginTop: 12 }}>
        <OptionalNotes value={note} onChange={(e) => setNote(e.target.value)} placeholder="e.g. Today's market rate" multiline={false} />
      </div>
      <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 16 }}>
        <Btn tone="ghost" onClick={onClose}>Cancel</Btn>
        <Btn tone="primary" onClick={submit} disabled={saving}>{saving ? "Saving…" : "Save Rate"}</Btn>
      </div>
    </Modal>
  );
}

/* =========================================================================
   COMPANY EXPENSES round — the Company Expenses page.
   Money the company spends (rent, salaries, fuel...) out of one of its own
   Cash in Hand accounts. All accounting happens on the server
   (src/expenses.js): every expense is one withdrawal on the paying Cash in
   Hand account, posted together with the expense or not at all. This page
   only shows, filters and submits. USD and SLSH are always shown separately
   — never added together and never converted.
   ========================================================================= */
const EXPENSE_PRESETS = [
  ["today", "Today"], ["week", "This Week"], ["month", "This Month"], ["lastMonth", "Last Month"],
  ["year", "This Year"], ["all", "All Time"], ["custom", "Custom Range"],
];
// The YYYY-MM-DD range for a period preset, in the browser's local time —
// the same plain-date convention the rest of the app's date filters use.
function expensePresetRange(preset) {
  const ymd = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  if (preset === "today") return { from: ymd(today), to: ymd(today) };
  if (preset === "week") { const s = new Date(today); s.setDate(s.getDate() - ((s.getDay() + 6) % 7)); return { from: ymd(s), to: ymd(today) }; }
  if (preset === "month") return { from: ymd(new Date(today.getFullYear(), today.getMonth(), 1)), to: ymd(today) };
  if (preset === "lastMonth") return { from: ymd(new Date(today.getFullYear(), today.getMonth() - 1, 1)), to: ymd(new Date(today.getFullYear(), today.getMonth(), 0)) };
  if (preset === "year") return { from: ymd(new Date(today.getFullYear(), 0, 1)), to: ymd(today) };
  return { from: "", to: "" };
}
function todayYMD() { return expensePresetRange("today").from; }
// A fresh id for each Add Expense form: re-sent on a retry so the server can
// recognise a repeated submission and never post the same expense twice.
// Short, stable fingerprint of a string (FNV-1a, 32-bit, hex) — used to tie
// an idempotency id to the exact content being submitted.
function fingerprint(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, "0");
}
function newRequestId() {
  try { if (window.crypto && window.crypto.randomUUID) return window.crypto.randomUUID(); } catch (e) { /* older browser */ }
  return `req-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}
const EXPENSE_STATUS_PILL = { posted: ["green", "Posted"], cancelled: ["slate", "Cancelled"] };

function ExpensesModule({ call, dl, notify, hasRaw, token }) {
  const canCreate = hasRaw("expenses.create");
  const canEdit = hasRaw("expenses.update");
  const canCancel = hasRaw("expenses.cancel");
  const canCategories = hasRaw("expenses.manageCategories");
  const canExport = hasRaw("expenses.export");

  const [tab, setTab] = useState("expenses");
  const [meta, setMeta] = useState(null);
  const [metaError, setMetaError] = useState(null);
  const [preset, setPreset] = useState("month");
  const [range, setRange] = useState(() => expensePresetRange("month"));
  const [currency, setCurrency] = useState("all");
  const [categoryId, setCategoryId] = useState("all");
  const [cashAccountId, setCashAccountId] = useState("all");
  const [status, setStatus] = useState("posted");
  const [searchInput, setSearchInput] = useState("");
  const [search, setSearch] = useState("");
  const [sort, setSort] = useState({ key: "date", dir: "desc" });
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(25);
  const [reloadTick, setReloadTick] = useState(0);
  const [summary, setSummary] = useState(null);
  const [summaryError, setSummaryError] = useState(null);
  const [list, setList] = useState(null);
  const [listLoading, setListLoading] = useState(true);
  const [listError, setListError] = useState(null);
  const [formOpen, setFormOpen] = useState(null); // null | { expense?: object }
  const [viewId, setViewId] = useState(null);
  const [cancelTarget, setCancelTarget] = useState(null);

  // Typing in the search box waits a moment before asking the server.
  useEffect(() => { const t = setTimeout(() => setSearch(searchInput.trim()), 350); return () => clearTimeout(t); }, [searchInput]);
  const loadMeta = useCallback(() => {
    setMetaError(null);
    call("/api/expenses/meta").then(setMeta).catch((e) => setMetaError(e.message));
  }, [call]);
  useEffect(loadMeta, [loadMeta]);

  const filters = { from: range.from, to: range.to, currency, categoryId, cashAccountId };
  const filterKey = JSON.stringify(filters);
  // Any change of filters goes back to the first page.
  useEffect(() => { setPage(1); }, [filterKey, status, search]);

  useEffect(() => {
    let live = true;
    setSummaryError(null);
    call("/api/expenses/summary" + qs(filters)).then((d) => { if (live) setSummary(d); }).catch((e) => { if (live) setSummaryError(e.message); });
    return () => { live = false; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [call, filterKey, reloadTick]);
  useEffect(() => {
    let live = true;
    setListLoading(true); setListError(null);
    call("/api/expenses" + qs({ ...filters, status, search, sort: sort.key, dir: sort.dir, page, pageSize }))
      .then((d) => { if (live) setList(d); })
      .catch((e) => { if (live) setListError(e.message); })
      .finally(() => { if (live) setListLoading(false); });
    return () => { live = false; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [call, filterKey, status, search, sort.key, sort.dir, page, pageSize, reloadTick]);

  const refreshAll = () => { setReloadTick((n) => n + 1); loadMeta(); };
  const onPreset = (p) => { setPreset(p); if (p !== "custom") setRange(expensePresetRange(p)); };
  const toggleSort = (key) => setSort((s) => (s.key === key ? { key, dir: s.dir === "asc" ? "desc" : "asc" } : { key, dir: key === "date" || key === "amount" ? "desc" : "asc" }));
  const showUSD = currency !== "SLSH", showSLSH = currency !== "USD";
  const t = summary && summary.totals;
  const accountsFor = (cur) => (meta ? meta.accounts.filter((a) => cur === "all" || a.currency === cur) : []);
  const filterBar = (
    <div className="gk-filterbar gk-exp-filters">
      <Field label="Period" width={130}>
        <Select value={preset} onChange={(e) => onPreset(e.target.value)} aria-label="Period">
          {EXPENSE_PRESETS.map(([k, l]) => <option key={k} value={k}>{l}</option>)}
        </Select>
      </Field>
      {preset === "custom" && (
        <>
          <Field label="From" width={150}><Input type="date" value={range.from} max={range.to || undefined} onChange={(e) => setRange((r) => ({ ...r, from: e.target.value }))} /></Field>
          <Field label="To" width={150}><Input type="date" value={range.to} min={range.from || undefined} onChange={(e) => setRange((r) => ({ ...r, to: e.target.value }))} /></Field>
        </>
      )}
      <Field label="Currency" width={100}>
        <Select value={currency} onChange={(e) => { setCurrency(e.target.value); setCashAccountId("all"); }}><option value="all">All</option><option value="USD">USD</option><option value="SLSH">SLSH</option></Select>
      </Field>
      <Field label="Category" width={160}>
        <Select value={categoryId} onChange={(e) => setCategoryId(e.target.value)}>
          <option value="all">All categories</option>
          {(meta ? meta.categories : []).map((c) => <option key={c.id} value={c.id}>{c.name}{c.status === "archived" ? " (archived)" : ""}</option>)}
        </Select>
      </Field>
      <Field label="Paid From" width={160}>
        <Select value={cashAccountId} onChange={(e) => setCashAccountId(e.target.value)}>
          <option value="all">All accounts</option>
          {accountsFor(currency).map((a) => <option key={a.id} value={a.id}>{toTitleCase(a.name)} ({a.currency})</option>)}
        </Select>
      </Field>
      {/* The expense list's search (it filters the Expenses table below). */}
      <div className="gk-exp-search" style={{ flex: "1 1 170px", minWidth: 170 }}><Field label="Search"><SearchInput placeholder="Description, reference, category…" value={searchInput} onChange={(e) => setSearchInput(e.target.value)} aria-label="Search expenses" /></Field></div>
    </div>
  );

  return (
    <div>
      <SectionHeader title="Company Expenses" sub="What the company spends, paid from its own Cash Accounts — USD and SLSH kept separate"
        actions={canCreate && <Btn tone="primary" icon="plus" onClick={() => setFormOpen({})} disabled={!meta}>Add New Expense</Btn>} />
      {metaError && <div role="alert" style={{ background: C.redBg, color: C.red, border: `1px solid ${C.red}`, borderRadius: 6, padding: "9px 12px", fontSize: 12.5, marginBottom: 12, display: "flex", justifyContent: "space-between", gap: 10, alignItems: "center" }}><span>Could not load expense categories and accounts. {metaError}</span><Btn size="sm" tone="ghost" onClick={loadMeta}>Try again</Btn></div>}

      {filterBar}

      {/* Dashboard cards — one per currency, never combined. */}
      <div className="gk-exp-cards" style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 12, marginBottom: 14 }}>
        {showUSD && <StatCard label="Total Expenses (USD)" value={t ? fmtMoney(t.USD.total, "USD") : summaryError ? "—" : "…"} sub={t ? `${t.USD.count} expense(s)` : undefined} accent={C.green} />}
        {showSLSH && <StatCard label="Total Expenses (SLSH)" value={t ? fmtMoney(t.SLSH.total, "SLSH") : summaryError ? "—" : "…"} sub={t ? `${t.SLSH.count} expense(s)` : undefined} accent={C.cyan} />}
        <StatCard label="Total Expense Transactions" value={summary ? String(summary.count) : summaryError ? "—" : "…"} accent={C.navyDeep} />
        <StatCard label="Average Expense" accent={C.amber}
          value={t ? [showUSD ? `${fmtMoney(t.USD.average, "USD")}` : null, showSLSH ? `${fmtMoney(t.SLSH.average, "SLSH")}` : null].filter(Boolean).join(" · ") : summaryError ? "—" : "…"}
          sub="Per expense, each currency on its own" />
      </div>
      {summaryError && <div role="alert" style={{ color: C.red, fontSize: 12.5, marginBottom: 10 }}>Could not load the expense summary. {summaryError}</div>}

      <ExpenseCharts summary={summary} showUSD={showUSD} showSLSH={showSLSH} />

      <div className="gk-tabbar" style={{ marginTop: 14 }} role="tablist">
        {[["expenses", "Expenses", "receipt"], ["reports", "Reports", "reports"], ...(canCategories ? [["categories", "Categories", "sliders"]] : [])].map(([k, l, icon]) => (
          <button key={k} role="tab" aria-selected={tab === k} onClick={() => setTab(k)} className={`gk-ph-tab${tab === k ? " is-active" : ""}`}><NavIcon name={icon} size={14} />{l}</button>
        ))}
      </div>

      {tab === "expenses" && (
        <>
          <div className="gk-filterbar">
            <Field label="Status" width={150}>
              <Select value={status} onChange={(e) => setStatus(e.target.value)}><option value="posted">Posted</option><option value="cancelled">Cancelled</option><option value="all">All</option></Select>
            </Field>
          </div>
          <div className="gk-table-wrap" style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 6, display: "flex", flexDirection: "column" }}>
            {listError ? (
              <div role="alert" style={{ padding: 24, textAlign: "center", color: C.red, fontSize: 13 }}>Could not load expenses. {listError}<div style={{ marginTop: 10 }}><Btn size="sm" tone="ghost" onClick={() => setReloadTick((n) => n + 1)}>Try again</Btn></div></div>
            ) : listLoading && !list ? <Spinner /> : !list || list.total === 0 ? (
              <Empty text={search || categoryId !== "all" || cashAccountId !== "all" || currency !== "all" || status !== "posted" ? "No expenses match these filters." : "No expenses recorded for this period yet."} />
            ) : (
              <>
                <TableScrollShell height={480}>
                  <ResizableTable tableKey="expenses.list" className="gk-table" style={{ width: "100%", borderCollapse: "collapse", opacity: listLoading ? 0.6 : 1 }}>
                    <thead><tr>
                      <SortTh label="#" />
                      <SortTh label="Date" field="date" sortKey={sort.key} sortDir={sort.dir} onSort={toggleSort} />
                      <SortTh label="Reference" field="reference" sortKey={sort.key} sortDir={sort.dir} onSort={toggleSort} />
                      <SortTh label="Category" field="category" sortKey={sort.key} sortDir={sort.dir} onSort={toggleSort} />
                      <SortTh label="Description" field="description" sortKey={sort.key} sortDir={sort.dir} onSort={toggleSort} />
                      <SortTh label="Amount" field="amount" sortKey={sort.key} sortDir={sort.dir} onSort={toggleSort} />
                      <SortTh label="Currency" field="currency" sortKey={sort.key} sortDir={sort.dir} onSort={toggleSort} />
                      <SortTh label="Paid From" field="paidFrom" sortKey={sort.key} sortDir={sort.dir} onSort={toggleSort} />
                      <SortTh label="Created By" field="createdBy" sortKey={sort.key} sortDir={sort.dir} onSort={toggleSort} />
                      <SortTh label="Status" field="status" sortKey={sort.key} sortDir={sort.dir} onSort={toggleSort} />
                      <SortTh label="Actions" />
                    </tr></thead>
                    <tbody>
                      {list.expenses.map((e, i) => {
                        const [tone, label] = EXPENSE_STATUS_PILL[e.status] || ["slate", e.status];
                        return (
                          <tr key={e.id} onClick={() => setViewId(e.id)} style={{ cursor: "pointer", opacity: e.status === "cancelled" ? 0.7 : 1 }}>
                            <td style={{ ...td, color: C.slate }}>{(list.page - 1) * list.pageSize + i + 1}</td>
                            <td style={td}>{fmtDate(e.date)}</td>
                            <td style={{ ...td, fontFamily: FONT_MONO, fontSize: 11.5 }} translate="no">{e.referenceNumber}</td>
                            <td style={td}>{e.categoryName}</td>
                            <td style={{ ...td, maxWidth: 320 }}>{e.description}{e.externalReference && <div style={{ fontSize: 11, color: C.slate }} translate="no">Ref: {e.externalReference}</div>}</td>
                            <td style={{ ...td, fontFamily: FONT_MONO, fontWeight: 700, textAlign: "right", fontVariantNumeric: "tabular-nums", textDecoration: e.status === "cancelled" ? "line-through" : "none" }}>{fmtMoney(e.amount, e.currency)}</td>
                            <td style={td}><Pill tone="cyan">{e.currency}</Pill></td>
                            <td style={td}>{e.cashAccount ? toTitleCase(e.cashAccount.name) : "—"}</td>
                            <td style={td}>{e.createdByName || "—"}</td>
                            <td style={td}><Pill tone={tone}>{label}</Pill></td>
                            <td style={td} onClick={(ev) => ev.stopPropagation()}>
                              <div style={{ display: "flex", gap: 4, flexWrap: "nowrap" }}>
                                <RowIconBtn icon="eye" label={`View ${e.referenceNumber}`} onClick={() => setViewId(e.id)} />
                                {canEdit && e.status === "posted" && <RowIconBtn icon="edit" label={`Edit ${e.referenceNumber}`} onClick={() => setFormOpen({ expense: e })} />}
                                {canCancel && e.status === "posted" && <RowIconBtn icon="ban" danger label={`Cancel ${e.referenceNumber}`} onClick={() => setCancelTarget(e)} />}
                              </div>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </ResizableTable>
                </TableScrollShell>
                <div style={{ display: "flex", gap: 18, flexWrap: "wrap", padding: "8px 12px", borderTop: `1px solid ${C.line}`, fontSize: 12, color: C.slate }}>
                  <span>Posted in this list:</span>
                  {showUSD && <span><b style={{ color: C.ink, fontFamily: FONT_MONO }}>{fmtMoney(list.totals.USD.total, "USD")}</b> ({list.totals.USD.count})</span>}
                  {showSLSH && <span><b style={{ color: C.ink, fontFamily: FONT_MONO }}>{fmtMoney(list.totals.SLSH.total, "SLSH")}</b> ({list.totals.SLSH.count})</span>}
                </div>
                <TableFooter firstIdx={(list.page - 1) * list.pageSize + 1} lastIdx={Math.min(list.total, list.page * list.pageSize)} total={list.total} page={list.page} totalPages={list.pages}
                  onPageChange={setPage} pageSize={list.pageSize} onPageSizeChange={(n) => { setPageSize(n); setPage(1); }} pageSizeOptions={[10, 25, 50, 100]} />
              </>
            )}
          </div>
        </>
      )}

      {tab === "reports" && <ExpenseReportsPanel call={call} dl={dl} notify={notify} filters={filters} canExport={canExport} />}
      {tab === "categories" && canCategories && <ExpenseCategoriesPanel call={call} notify={notify} meta={meta} onChanged={refreshAll} />}

      {formOpen && meta && (
        <ExpenseFormModal call={call} notify={notify} meta={meta} expense={formOpen.expense || null}
          onClose={() => setFormOpen(null)} onSaved={() => { setFormOpen(null); refreshAll(); }} />
      )}
      {viewId && (
        <ExpenseViewModal id={viewId} call={call} token={token} notify={notify}
          canEdit={canEdit} canCancel={canCancel}
          onClose={() => setViewId(null)}
          onEdit={(e) => { setViewId(null); setFormOpen({ expense: e }); }}
          onCancelExpense={(e) => { setViewId(null); setCancelTarget(e); }} />
      )}
      {cancelTarget && (
        <CancelExpenseModal call={call} notify={notify} expense={cancelTarget}
          onClose={() => setCancelTarget(null)} onDone={() => { setCancelTarget(null); refreshAll(); }} />
      )}
    </div>
  );
}

// Expense charts: over time and by category. Each currency gets its own
// chart, so USD and SLSH are never drawn on one axis as if comparable.
function ExpenseCharts({ summary, showUSD, showSLSH }) {
  // Compact: one card per currency (never mixing USD and SLSH), side by side
  // on desktop. Inside each card the over-time bars and the top categories sit
  // next to each other, so the whole card stays around 200px tall.
  if (!summary) return <div style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 6 }}><Spinner label="Loading charts…" /></div>;
  const curs = [showUSD && "USD", showSLSH && "SLSH"].filter(Boolean);
  const colors = { USD: C.chartBlue, SLSH: C.chartGreen };
  const unitLabel = { day: "day", week: "week", month: "month", year: "year" }[summary.bucketUnit] || summary.bucketUnit;
  return (
    <div className="gk-exp-charts" style={{ display: "grid", gridTemplateColumns: `repeat(${curs.length}, minmax(0, 1fr))`, gap: 12 }}>
      {curs.map((cur) => {
        const hasData = summary.byDate.some((b) => b[cur] > 0);
        const cats = summary.byCategory.filter((c) => c[cur] > 0).sort((a, b) => b[cur] - a[cur]);
        const top = cats.slice(0, 3);
        const others = cats.slice(3).reduce((t, c) => t + c[cur], 0);
        const max = Math.max(1, ...top.map((c) => c[cur]), others);
        return (
          <div key={cur} className="gk-exp-chart-card" data-currency={cur} style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 6, padding: "10px 12px", minWidth: 0 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 8, marginBottom: 6, flexWrap: "wrap" }}>
              <div style={{ fontSize: 12.5, fontWeight: 700, color: C.ink }}>Expenses over time — {cur}</div>
              <div style={{ fontSize: 11, color: C.slate }}>Grouped by {unitLabel}</div>
            </div>
            {!hasData ? (
              <div style={{ height: 150, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 12, color: C.slate, background: C.paper, borderRadius: 6, border: `1px dashed ${C.line}` }}>No {cur} expenses in this period.</div>
            ) : (
              <div className="gk-exp-chart-body" style={{ display: "grid", gridTemplateColumns: "minmax(0, 3fr) minmax(0, 2fr)", gap: 14, alignItems: "end" }}>
                <div style={{ minWidth: 0 }}>
                  <GroupedBarChart labels={summary.byDate.map((b) => b.bucket)} series={[{ name: `Expenses (${cur})`, color: colors[cur], data: summary.byDate.map((b) => b[cur]) }]}
                    height={112} format={(v) => fmtMoney(v, cur)} />
                </div>
                <div style={{ minWidth: 0, alignSelf: "start" }}>
                  <div style={{ fontSize: 11, fontWeight: 700, color: C.slate, textTransform: "uppercase", letterSpacing: 0.4, marginBottom: 6 }}>By category — {cur}</div>
                  {[...top, ...(others > 0 ? [{ categoryId: "_others", categoryName: `Other categories (${cats.length - 3})`, [cur]: others }] : [])].map((c) => (
                    <div key={c.categoryId} title={`${c.categoryName}: ${fmtMoney(c[cur], cur)}`} style={{ marginBottom: 6 }}>
                      <div style={{ display: "flex", justifyContent: "space-between", gap: 6, fontSize: 11 }}>
                        <span style={{ color: C.ink, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", minWidth: 0 }}>{c.categoryName}</span>
                        <span style={{ fontFamily: FONT_MONO, color: C.slate, whiteSpace: "nowrap" }} translate="no">{fmtMoney(c[cur], cur)}</span>
                      </div>
                      <div style={{ background: C.slateBg, borderRadius: 3, height: 6, marginTop: 2 }}>
                        <div style={{ width: `${Math.max(3, (c[cur] / max) * 100)}%`, background: colors[cur], height: 6, borderRadius: 3 }} />
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

function ExpenseFormModal({ call, notify, meta, expense, onClose, onSaved }) {
  const editing = !!expense;
  const requestIdRef = useRef(newRequestId());
  const activeCats = meta.categories.filter((c) => c.status === "active" || (editing && c.id === expense.categoryId));
  const [f, setF] = useState(() => ({
    date: editing ? String(expense.date).slice(0, 10) : todayYMD(),
    categoryId: editing ? expense.categoryId : "",
    description: editing ? expense.description : "",
    amount: editing ? String(expense.amount) : "",
    currency: editing ? expense.currency : "USD",
    cashAccountId: editing ? expense.cashAccountId : "",
    externalReference: editing ? (expense.externalReference || "") : "",
    notes: editing ? (expense.notes || "") : "",
  }));
  const [attachment, setAttachment] = useState(undefined); // undefined = unchanged, null = remove, {fileName,dataUrl}
  const [existingAttachment, setExistingAttachment] = useState(null);
  const [errors, setErrors] = useState({});
  const [formError, setFormError] = useState(null);
  const [saving, setSaving] = useState(false);
  useEffect(() => {
    if (!editing) return;
    call(`/api/expenses/${expense.id}`).then((d) => setExistingAttachment(d.expense.attachment)).catch(() => {});
  }, [call, editing, expense]);
  const set = (k, v) => { setF((p) => ({ ...p, [k]: v })); setErrors((e) => ({ ...e, [k]: undefined })); };
  const accounts = meta.accounts.filter((a) => a.currency === f.currency || (editing && a.id === expense.cashAccountId && a.currency === f.currency));
  const chosen = meta.accounts.find((a) => a.id === f.cashAccountId);
  const amountNum = Number(String(f.amount).replace(/,/g, ""));

  function validate() {
    const e = {};
    if (!f.date) e.date = "Expense Date is required.";
    if (!f.categoryId) e.categoryId = "Expense Category is required.";
    if (!f.description.trim()) e.description = "Description is required.";
    if (String(f.amount).trim() === "") e.amount = "Amount is required.";
    else if (!Number.isFinite(amountNum)) e.amount = "Amount must be a number.";
    else if (amountNum <= 0) e.amount = "Amount must be greater than zero.";
    if (!f.cashAccountId) e.cashAccountId = "Paid From Account is required.";
    else if (chosen && chosen.currency !== f.currency) e.cashAccountId = "Choose an account in the same currency as the expense.";
    return e;
  }
  function pickFile(file) {
    if (!file) return;
    const okType = ["image/png", "image/jpeg", "application/pdf"].includes(file.type);
    if (!okType) { setErrors((e) => ({ ...e, attachment: "Receipt must be a PNG, JPEG or PDF file." })); return; }
    if (file.size > 3 * 1024 * 1024) { setErrors((e) => ({ ...e, attachment: "Receipt file is too large (maximum 3 MB)." })); return; }
    const r = new FileReader();
    r.onload = () => { setAttachment({ fileName: file.name, dataUrl: String(r.result) }); setErrors((e) => ({ ...e, attachment: undefined })); };
    r.onerror = () => setErrors((e) => ({ ...e, attachment: "The receipt file could not be read." }));
    r.readAsDataURL(file);
  }
  async function submit() {
    if (saving) return; // a second click while saving does nothing
    const e = validate();
    setErrors(e); setFormError(null);
    if (Object.keys(e).length) return;
    setSaving(true);
    const body = {
      date: f.date, categoryId: f.categoryId, description: f.description.trim(), amount: amountNum,
      currency: f.currency, cashAccountId: f.cashAccountId, externalReference: f.externalReference.trim(), notes: f.notes.trim(),
      ...(attachment !== undefined ? { attachment } : {}),
    };
    try {
      if (editing) {
        await call(`/api/expenses/${expense.id}`, { method: "PATCH", body });
        notify("Expense updated.");
      } else {
        const r = await call("/api/expenses", { method: "POST", body: { ...body, clientRequestId: requestIdRef.current } });
        notify(r.duplicate ? "This expense was already saved." : `Expense ${r.expense.referenceNumber} recorded.`);
      }
      onSaved();
    } catch (err) {
      // Everything typed stays in the form so it can be corrected and resent;
      // a resend reuses the same request id, so it can never post twice.
      const fld = err.data && err.data.field;
      if (fld) setErrors((x) => ({ ...x, [fld]: err.message }));
      setFormError(err.message || "Saving failed.");
    } finally {
      setSaving(false);
    }
  }
  const errStyle = { color: C.red, fontSize: 11.5, marginTop: 3 };
  const fieldErr = (k) => errors[k] ? <div style={errStyle} role="alert">{errors[k]}</div> : null;
  return (
    <Modal title={editing ? `Edit Expense ${expense.referenceNumber}` : "Add New Expense"} subtitle={editing ? "Changes here also correct the paying account's cash movement." : "The amount is taken out of the chosen Cash Account."} onClose={saving ? () => {} : onClose} width={640}>
      <form onSubmit={(ev) => { ev.preventDefault(); submit(); }} noValidate>
        <div className="gk-exp-form-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
          <Field label="Expense Date *"><Input type="date" value={f.date} onChange={(e) => set("date", e.target.value)} aria-invalid={!!errors.date} />{fieldErr("date")}</Field>
          <Field label="Expense Category *">
            <Select value={f.categoryId} onChange={(e) => set("categoryId", e.target.value)} aria-invalid={!!errors.categoryId}>
              <option value="">Choose a category…</option>
              {activeCats.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
            </Select>{fieldErr("categoryId")}
          </Field>
          <div style={{ gridColumn: "1 / -1" }}>
            <Field label="Description *"><Input value={f.description} maxLength={500} onChange={(e) => set("description", e.target.value)} placeholder="What was paid for" aria-invalid={!!errors.description} />{fieldErr("description")}</Field>
          </div>
          <Field label="Amount *"><MoneyInput value={f.amount} onChange={(e) => set("amount", e.target.value)} placeholder="0.00" aria-invalid={!!errors.amount} />{fieldErr("amount")}</Field>
          <Field label="Currency *">
            <Select value={f.currency} onChange={(e) => { set("currency", e.target.value); set("cashAccountId", ""); }}><option value="USD">USD</option><option value="SLSH">SLSH</option></Select>
          </Field>
          <div style={{ gridColumn: "1 / -1" }}>
            <Field label="Paid From Account *">
              <Select value={f.cashAccountId} onChange={(e) => set("cashAccountId", e.target.value)} aria-invalid={!!errors.cashAccountId}>
                <option value="">{accounts.length ? "Choose a Cash Account…" : `No active ${f.currency} Cash Account`}</option>
                {accounts.map((a) => <option key={a.id} value={a.id}>{toTitleCase(a.name)} — {a.currency}{a.balance !== undefined ? ` (${fmtMoney(a.balance, a.currency)})` : ""}</option>)}
              </Select>{fieldErr("cashAccountId")}
              {chosen && chosen.balance !== undefined && Number.isFinite(amountNum) && amountNum > 0 && !editing && (
                <div style={{ fontSize: 11.5, color: chosen.balance - amountNum < 0 ? C.amber : C.slate, marginTop: 4 }}>
                  Balance after this expense: <b translate="no">{fmtMoney(chosen.balance - amountNum, chosen.currency)}</b>{chosen.balance - amountNum < 0 ? " — this account will go negative." : ""}
                </div>
              )}
            </Field>
          </div>
          <Field label="Reference Number"><Input value={f.externalReference} maxLength={100} onChange={(e) => set("externalReference", e.target.value)} placeholder="Invoice or receipt number (optional)" /></Field>
          <Field label="Receipt / Attachment">
            <div style={{ display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap" }}>
              <label className="gk-icon-btn" style={{ display: "inline-flex", alignItems: "center", gap: 6, border: `1px solid ${C.line}`, borderRadius: 5, padding: "5px 10px", fontSize: 12, fontWeight: 600, color: C.navy, cursor: "pointer", background: C.card }}>
                <NavIcon name="upload" size={13} />{attachment || existingAttachment ? "Replace file" : "Upload file"}
                <input type="file" accept="image/png,image/jpeg,application/pdf" style={{ display: "none" }} onChange={(e) => pickFile(e.target.files && e.target.files[0])} />
              </label>
              {attachment ? <span style={{ fontSize: 11.5, color: C.slate }} translate="no">{attachment.fileName}</span>
                : attachment === null ? <span style={{ fontSize: 11.5, color: C.slate }}>Will be removed</span>
                  : existingAttachment ? <span style={{ fontSize: 11.5, color: C.slate }} translate="no">{existingAttachment.fileName}</span> : null}
              {(attachment || (existingAttachment && attachment !== null)) && <Btn size="sm" tone="ghost" type="button" onClick={() => setAttachment(editing && existingAttachment ? null : undefined)}>Remove</Btn>}
            </div>
            <div style={{ fontSize: 11, color: C.slate, marginTop: 3 }}>PNG, JPEG or PDF, up to 3 MB.</div>
            {fieldErr("attachment")}
          </Field>
          <div style={{ gridColumn: "1 / -1" }}>
            <OptionalNotes value={f.notes} maxLength={2000} onChange={(e) => set("notes", e.target.value)} />
          </div>
        </div>
        {formError && <div role="alert" style={{ background: C.redBg, color: C.red, borderRadius: 5, padding: "8px 11px", fontSize: 12.5, marginTop: 12 }}>{formError}</div>}
        <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 16 }}>
          <Btn tone="ghost" type="button" onClick={onClose} disabled={saving}>Cancel</Btn>
          <Btn tone="primary" type="submit" disabled={saving}>{saving ? "Saving…" : editing ? "Save changes" : "Save Expense"}</Btn>
        </div>
      </form>
    </Modal>
  );
}

function ExpenseViewModal({ id, call, token, notify, canEdit, canCancel, onClose, onEdit, onCancelExpense }) {
  const [e, setE] = useState(null);
  const [error, setError] = useState(null);
  const [receiptUrl, setReceiptUrl] = useState(null);
  useEffect(() => {
    let live = true;
    call(`/api/expenses/${id}`).then((d) => { if (live) setE(d.expense); }).catch((err) => { if (live) setError(err.message); });
    return () => { live = false; };
  }, [call, id]);
  useEffect(() => () => { if (receiptUrl) URL.revokeObjectURL(receiptUrl); }, [receiptUrl]);
  async function openReceipt(download) {
    try {
      // Fetched with the signed-in session — a receipt has no public link.
      const url = await fetchBlobUrl(`/api/expenses/${id}/attachment${download ? "?download=1" : ""}`, token);
      if (download) { const a = document.createElement("a"); a.href = url; a.download = e.attachment.fileName; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 5000); }
      else setReceiptUrl(url);
    } catch (err) { notify(err.message, true); }
  }
  const row = (label, value, mono) => (
    <div style={{ display: "flex", gap: 12, padding: "8px 0", borderBottom: `1px solid ${C.line}`, fontSize: 12.5 }}>
      <div style={{ width: 150, color: C.slate, flexShrink: 0 }}>{label}</div>
      <div style={{ color: C.ink, fontWeight: 600, fontFamily: mono ? FONT_MONO : undefined, minWidth: 0, overflowWrap: "anywhere" }}>{value}</div>
    </div>
  );
  return (
    <Modal title={e ? <span translate="no">{e.referenceNumber}</span> : "Expense"} subtitle={e ? `${e.categoryName} · ${fmtDate(e.date)}` : undefined} onClose={onClose} width={620}>
      {error ? <div role="alert" style={{ color: C.red, fontSize: 13 }}>Could not load this expense. {error}</div> : !e ? <Spinner /> : (
        <div>
          {e.status === "cancelled" && (
            <div style={{ background: C.slateBg, borderRadius: 6, padding: "9px 12px", fontSize: 12.5, marginBottom: 10 }}>
              <b>Cancelled</b> on {fmtDate(e.cancelledAt)} by {e.cancelledByName || "—"}. Reason: {e.cancelReason}
            </div>
          )}
          {row("Amount", <span style={{ fontSize: 15 }}>{fmtMoney(e.amount, e.currency)}</span>, true)}
          {row("Description", e.description)}
          {row("Category", e.categoryName)}
          {row("Paid From", e.cashAccount ? `${toTitleCase(e.cashAccount.name)} (${e.cashAccount.currency})` : "—")}
          {row("Reference Number", e.externalReference ? <span translate="no">{e.externalReference}</span> : "—")}
          {row("Cash movement", e.ledgerEntry ? <span translate="no">{e.ledgerEntry.referenceNumber}</span> : "—", true)}
          {e.reversalEntry && row("Reversal movement", <span translate="no">{e.reversalEntry.referenceNumber}</span>, true)}
          {row("Created By", `${e.createdByName || "—"} · ${fmtDateTime(e.createdAt)}`)}
          {e.updatedAt && row("Last Edited", `${e.updatedByName || "—"} · ${fmtDateTime(e.updatedAt)}`)}
          {row("Status", <Pill tone={(EXPENSE_STATUS_PILL[e.status] || ["slate"])[0]}>{(EXPENSE_STATUS_PILL[e.status] || [null, e.status])[1]}</Pill>)}
          {e.notes && row("Notes", e.notes)}
          {row("Receipt", e.attachment ? (
            <span style={{ display: "inline-flex", gap: 6, alignItems: "center", flexWrap: "wrap" }}>
              <span translate="no">{e.attachment.fileName}</span>
              <Btn size="sm" tone="ghost" icon="eye" onClick={() => openReceipt(false)}>View</Btn>
              <Btn size="sm" tone="ghost" icon="download" onClick={() => openReceipt(true)}>Download</Btn>
            </span>
          ) : "No receipt attached")}
          {receiptUrl && (
            e.attachment.mimeType === "application/pdf"
              ? <iframe title="Receipt" src={receiptUrl} style={{ width: "100%", height: 380, border: `1px solid ${C.line}`, borderRadius: 6, marginTop: 10 }} />
              : <img alt="Receipt" src={receiptUrl} style={{ maxWidth: "100%", maxHeight: 420, display: "block", margin: "10px auto 0", borderRadius: 6, border: `1px solid ${C.line}` }} />
          )}
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 16, flexWrap: "wrap" }}>
            {canCancel && e.status === "posted" && <Btn tone="danger" icon="ban" onClick={() => onCancelExpense(e)}>Cancel Expense</Btn>}
            {canEdit && e.status === "posted" && <Btn tone="ghost" icon="edit" onClick={() => onEdit(e)}>Edit</Btn>}
            <Btn tone="primary" onClick={onClose}>Close</Btn>
          </div>
        </div>
      )}
    </Modal>
  );
}

function CancelExpenseModal({ call, notify, expense, onClose, onDone }) {
  const [reason, setReason] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);
  async function submit() {
    if (saving) return;
    if (!reason.trim()) { setError("Enter a reason for cancelling this expense."); return; }
    setSaving(true); setError(null);
    try {
      await call(`/api/expenses/${expense.id}/cancel`, { method: "POST", body: { reason: reason.trim() } });
      notify(`Expense ${expense.referenceNumber} cancelled — the amount was returned to the paying account.`);
      onDone();
    } catch (err) { setError(err.message); } finally { setSaving(false); }
  }
  return (
    <Modal title={<span>Cancel expense <span translate="no">{expense.referenceNumber}</span>?</span>} onClose={saving ? () => {} : onClose} width={480}>
      <div style={{ fontSize: 12.5, color: C.slate, lineHeight: 1.6, marginBottom: 12 }}>
        <b style={{ color: C.ink }} translate="no">{fmtMoney(expense.amount, expense.currency)}</b> will be returned to the paying account by a reversing entry. The original expense and its cash movement stay in the history, marked as cancelled. This can't be undone.
      </div>
      <Field label="Reason *"><TextArea value={reason} maxLength={500} onChange={(e) => { setReason(e.target.value); setError(null); }} placeholder="Why is this expense being cancelled?" /></Field>
      {error && <div role="alert" style={{ color: C.red, fontSize: 12, marginTop: 6 }}>{error}</div>}
      <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 14 }}>
        <Btn tone="ghost" onClick={onClose} disabled={saving}>Keep Expense</Btn>
        <Btn tone="danger" onClick={submit} disabled={saving}>{saving ? "Cancelling…" : "Cancel Expense"}</Btn>
      </div>
    </Modal>
  );
}

const EXPENSE_REPORT_GROUPS = [
  ["day", "Daily"], ["week", "Weekly"], ["month", "Monthly"], ["year", "Yearly"],
  ["category", "By Category"], ["account", "By Payment Account"], ["currency", "By Currency"], ["detail", "Detailed Transactions"],
];
const EXPENSE_REPORT_KEY = { day: "Date", week: "Week starting", month: "Month", year: "Year", category: "Category", account: "Paid From", currency: "Currency" };

function ExpenseReportsPanel({ call, dl, notify, filters, canExport }) {
  const [groupBy, setGroupBy] = useState("month");
  const [rep, setRep] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const q = qs({ ...filters, groupBy });
  useEffect(() => {
    let live = true;
    setLoading(true); setError(null);
    call("/api/expenses/report" + q).then((d) => { if (live) setRep(d); }).catch((e) => { if (live) setError(e.message); }).finally(() => { if (live) setLoading(false); });
    return () => { live = false; };
  }, [call, q]);
  const isDetail = groupBy === "detail";
  return (
    <div>
      <div className="gk-filterbar">
        <Field label="Report" width={220}>
          <Select value={groupBy} onChange={(e) => setGroupBy(e.target.value)}>{EXPENSE_REPORT_GROUPS.map(([k, l]) => <option key={k} value={k}>{l}</option>)}</Select>
        </Field>
        <div style={{ fontSize: 11.5, color: C.slate, paddingBottom: 8 }}>Uses the period, currency, category and account filters above. Posted expenses only.</div>
        {canExport && (
          <div style={{ display: "flex", gap: 6, marginLeft: "auto" }}>
            <Btn size="sm" tone="ghost" icon="download" onClick={() => dl(`/api/expenses/report/export.csv${q}`, `obo-expenses-${groupBy}.csv`)}>Export CSV</Btn>
            <Btn size="sm" tone="ghost" icon="download" onClick={() => dl(`/api/expenses/report/export.xlsx${q}`, `obo-expenses-${groupBy}.xlsx`)}>Export Excel</Btn>
            <Btn size="sm" tone="ghost" icon="download" onClick={() => dl(`/api/expenses/report/export.pdf${q}`, `obo-expenses-${groupBy}.pdf`)}>Export PDF</Btn>
          </div>
        )}
      </div>
      <div className="gk-table-wrap" style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 6 }}>
        {error ? <div role="alert" style={{ padding: 24, color: C.red, textAlign: "center", fontSize: 13 }}>Could not load the report. {error}</div>
          : loading && !rep ? <Spinner /> : !rep || rep.rows.length === 0 ? <Empty text="No expenses in this period." /> : (
            <TableScrollShell height={460}>
              <table className="gk-table" style={{ width: "100%", borderCollapse: "collapse", opacity: loading ? 0.6 : 1 }}>
                <thead>
                  {isDetail ? (
                    <tr><th style={th}>Date</th><th style={th}>Reference</th><th style={th}>Category</th><th style={th}>Description</th><th style={th}>Paid From</th><th style={{ ...th, textAlign: "right" }}>Amount</th><th style={th}>Created By</th></tr>
                  ) : (
                    <tr><th style={th}>{EXPENSE_REPORT_KEY[groupBy]}</th><th style={{ ...th, textAlign: "right" }}>Expenses (USD)</th><th style={{ ...th, textAlign: "right" }}>Count (USD)</th><th style={{ ...th, textAlign: "right" }}>Expenses (SLSH)</th><th style={{ ...th, textAlign: "right" }}>Count (SLSH)</th></tr>
                  )}
                </thead>
                <tbody>
                  {isDetail ? rep.rows.map((r, i) => (
                    <tr key={i}><td style={td}>{fmtDate(r.date)}</td><td style={{ ...td, fontFamily: FONT_MONO, fontSize: 11.5 }} translate="no">{r.reference}</td><td style={td}>{r.category}</td><td style={td}>{r.description}</td><td style={td}>{toTitleCase(r.paidFrom)}</td><td style={{ ...td, textAlign: "right", fontFamily: FONT_MONO }}>{fmtMoney(r.amount, r.currency)}</td><td style={td}>{r.createdBy}</td></tr>
                  )) : rep.rows.map((r) => (
                    <tr key={r.key}>
                      <td style={td}>{groupBy === "day" ? fmtDate(r.key) : groupBy === "account" ? toTitleCase(r.key) : r.key}</td>
                      <td style={{ ...td, textAlign: "right", fontFamily: FONT_MONO }}>{fmtMoney(r.USD, "USD")}</td>
                      <td style={{ ...td, textAlign: "right" }}>{r.countUSD}</td>
                      <td style={{ ...td, textAlign: "right", fontFamily: FONT_MONO }}>{fmtMoney(r.SLSH, "SLSH")}</td>
                      <td style={{ ...td, textAlign: "right" }}>{r.countSLSH}</td>
                    </tr>
                  ))}
                </tbody>
                <tfoot>
                  {isDetail ? (
                    <>
                      <tr><td style={{ ...td, fontWeight: 700 }} colSpan={5}>Total (USD)</td><td style={{ ...td, textAlign: "right", fontWeight: 700, fontFamily: FONT_MONO }}>{fmtMoney(rep.grand.USD, "USD")}</td><td style={td}>{rep.grand.countUSD}</td></tr>
                      <tr><td style={{ ...td, fontWeight: 700 }} colSpan={5}>Total (SLSH)</td><td style={{ ...td, textAlign: "right", fontWeight: 700, fontFamily: FONT_MONO }}>{fmtMoney(rep.grand.SLSH, "SLSH")}</td><td style={td}>{rep.grand.countSLSH}</td></tr>
                    </>
                  ) : (
                    <tr>
                      <td style={{ ...td, fontWeight: 700 }}>Total</td>
                      <td style={{ ...td, textAlign: "right", fontWeight: 700, fontFamily: FONT_MONO }}>{fmtMoney(rep.grand.USD, "USD")}</td>
                      <td style={{ ...td, textAlign: "right", fontWeight: 700 }}>{rep.grand.countUSD}</td>
                      <td style={{ ...td, textAlign: "right", fontWeight: 700, fontFamily: FONT_MONO }}>{fmtMoney(rep.grand.SLSH, "SLSH")}</td>
                      <td style={{ ...td, textAlign: "right", fontWeight: 700 }}>{rep.grand.countSLSH}</td>
                    </tr>
                  )}
                </tfoot>
              </table>
            </TableScrollShell>
          )}
      </div>
    </div>
  );
}

function ExpenseCategoriesPanel({ call, notify, meta, onChanged }) {
  const [name, setName] = useState("");
  const [saving, setSaving] = useState(false);
  const [editing, setEditing] = useState(null); // { id, name }
  const cats = meta ? meta.categories : [];
  async function add() {
    if (saving || !name.trim()) return;
    setSaving(true);
    try { await call("/api/expense-categories", { method: "POST", body: { name: name.trim() } }); notify("Category added."); setName(""); onChanged(); }
    catch (e) { notify(e.message, true); } finally { setSaving(false); }
  }
  async function update(id, body, msg) {
    try { await call(`/api/expense-categories/${id}`, { method: "PATCH", body }); notify(msg); setEditing(null); onChanged(); }
    catch (e) { notify(e.message, true); }
  }
  return (
    <div>
      <div style={{ display: "flex", gap: 8, alignItems: "flex-end", marginBottom: 12, flexWrap: "wrap" }}>
        <Field label="New category" width={280}><Input value={name} maxLength={80} onChange={(e) => setName(e.target.value)} onKeyDown={(e) => e.key === "Enter" && add()} placeholder="e.g. Security" /></Field>
        <Btn tone="primary" icon="plus" onClick={add} disabled={saving || !name.trim()}>Add Category</Btn>
      </div>
      <div style={{ fontSize: 11.5, color: C.slate, marginBottom: 10 }}>A category that is no longer needed can be archived: it disappears from the form, while expenses already recorded keep it.</div>
      <div className="gk-table-wrap" style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 6 }}>
        {!meta ? <Spinner /> : cats.length === 0 ? <Empty text="No categories yet." /> : (
          <table className="gk-table" style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead><tr><th style={th}>Category</th><th style={th}>Used by</th><th style={th}>Status</th><th style={th}>Actions</th></tr></thead>
            <tbody>
              {cats.map((c) => (
                <tr key={c.id}>
                  <td style={td}>{editing && editing.id === c.id ? (
                    <div style={{ display: "flex", gap: 6 }}>
                      <Input value={editing.name} maxLength={80} autoFocus onChange={(e) => setEditing({ ...editing, name: e.target.value })} onKeyDown={(e) => { if (e.key === "Enter") update(c.id, { name: editing.name }, "Category renamed."); if (e.key === "Escape") setEditing(null); }} />
                      <Btn size="sm" tone="primary" onClick={() => update(c.id, { name: editing.name }, "Category renamed.")}>Save</Btn>
                      <Btn size="sm" tone="ghost" onClick={() => setEditing(null)}>Cancel</Btn>
                    </div>
                  ) : c.name}</td>
                  <td style={td}>{c.usedCount} expense(s)</td>
                  <td style={td}>{c.status === "active" ? <Pill tone="green">Active</Pill> : <Pill tone="slate">Archived</Pill>}</td>
                  <td style={td}>
                    <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                      {!(editing && editing.id === c.id) && <Btn size="sm" tone="ghost" icon="edit" onClick={() => setEditing({ id: c.id, name: c.name })}>Rename</Btn>}
                      {c.status === "active"
                        ? <Btn size="sm" tone="ghost" onClick={() => update(c.id, { status: "archived" }, "Category archived.")}>Archive</Btn>
                        : <Btn size="sm" tone="ghost" onClick={() => update(c.id, { status: "active" }, "Category restored.")}>Restore</Btn>}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

// BALANCE SHEET round (four-card layout): a section of its own BELOW the four
// original Cash in Hand cards, which stay exactly as they were.
//   1. Balance Sheet (USD)  = Debt + Cash in Hand − Credit, in USD only
//   2. Balance Sheet (SLSH) = the same, in SLSH only
//   3. Exchange Rate — the Cash in Hand rate that has actually been set
//   4. Net Balance Sheet — both results combined into ONE amount in one named
//      reporting currency (SLSH Equivalent by default, or USD Equivalent),
//      converted with that Cash in Hand rate on the server from the precise
//      values. With no Cash in Hand rate set it says so instead of borrowing
//      the Money Exchange Daily Rate.
// Every figure comes from GET /api/cash/balance-sheet (see its comment in
// routes/cash.js for exactly which records count).
const NET_BS_PREF_KEY = "obo_net_balance_sheet_currency";
function BalanceSheetCard({ data, error, canEditRate, onEditRate }) {
  const [reporting, setReporting] = useState(() => { try { return localStorage.getItem(NET_BS_PREF_KEY) === "USD" ? "USD" : "SLSH"; } catch (e) { return "SLSH"; } });
  const pickReporting = (v) => { setReporting(v); try { localStorage.setItem(NET_BS_PREF_KEY, v); } catch (e) { /* private mode */ } };
  const money = (v, cur) => <span translate="no" style={{ fontFamily: FONT_MONO, fontVariantNumeric: "tabular-nums" }}>{fmtMoney(v, cur)}</span>;
  const shell = (accent, children, extra) => (
    <div className="gk-bs-card" {...extra} style={{ background: C.card, border: `1px solid ${C.line}`, borderLeft: `4px solid ${accent}`, borderRadius: 8, padding: "12px 14px", minWidth: 0, display: "flex", flexDirection: "column", gap: 8 }}>{children}</div>
  );
  const head = (icon, title, sub, accent) => (
    <div style={{ display: "flex", alignItems: "flex-start", gap: 8 }}>
      <span aria-hidden="true" style={{ width: 26, height: 26, borderRadius: 7, display: "inline-flex", alignItems: "center", justifyContent: "center", background: `color-mix(in srgb, ${accent} 14%, transparent)`, color: accent, flexShrink: 0 }}><NavIcon name={icon} size={14} /></span>
      <div style={{ minWidth: 0 }}>
        <div style={{ fontSize: 12.5, fontWeight: 700, color: C.ink, lineHeight: 1.3 }}>{title}</div>
        {sub && <div style={{ fontSize: 10.5, color: C.slate, lineHeight: 1.3 }}>{sub}</div>}
      </div>
    </div>
  );
  const big = (node, color) => <div className="gk-bs-value" style={{ fontSize: 20, fontWeight: 800, color, lineHeight: 1.15, overflowWrap: "anywhere" }}>{node}</div>;
  const row = (label, node, sign) => (
    <div style={{ display: "flex", justifyContent: "space-between", gap: 8, fontSize: 11.5, color: C.slate, padding: "2px 0" }}>
      <span>{label}</span><span style={{ color: C.ink, fontWeight: 600, whiteSpace: "nowrap" }}>{sign && <span style={{ color: C.slate, marginRight: 3 }}>{sign}</span>}{node}</span>
    </div>
  );
  const breakdown = (children) => <div style={{ borderTop: `1px dashed ${C.line}`, paddingTop: 6, marginTop: "auto" }}>{children}</div>;

  const currencyCard = (cur) => {
    const b = data && data.currencies[cur];
    if (!b) {
      return shell(C.slate, <>{head(cur === "USD" ? "accountsUsd" : "accountsSlsh", `Balance Sheet (${cur})`, "Debt + Cash Account − Credit", C.slate)}<div style={{ fontSize: 12, color: C.slate }}>{data ? `No access to ${cur} accounts.` : "…"}</div></>, { "data-card": cur.toLowerCase(), "data-currency": cur });
    }
    const tone = b.balanceSheet < 0 ? C.red : C.green;
    return shell(tone, (
      <>
        {head(cur === "USD" ? "accountsUsd" : "accountsSlsh", `Balance Sheet (${cur})`, "Debt + Cash Account − Credit", tone)}
        {big(<span className="gk-balance-sheet-total">{money(b.balanceSheet, cur)}</span>, tone)}
        {breakdown(<>
          {row(`Total Debt (${cur})`, money(b.debt, cur), "+")}
          {row(`Total Cash Account (${cur})`, money(b.cashInHand, cur), "+")}
          {row(`Total Credit (${cur})`, money(b.credit, cur), "−")}
        </>)}
      </>
    ), { "data-card": cur.toLowerCase(), "data-currency": cur });
  };

  const rateCard = () => {
    const r = data && data.cashRate;
    return shell(C.amber, (
      <>
        {head("exchange", "Exchange Rate", "Cash Account only", C.amber)}
        {big(!data ? "…" : r ? <span translate="no" style={{ fontFamily: FONT_MONO }}>$1 = SLSH {fmtNum(r.rate)}</span> : <span style={{ fontSize: 15 }}>Not set</span>, C.ink)}
        {breakdown(<>
          {r ? <div style={{ fontSize: 11, color: C.slate }}>Set by {r.setByName || "—"} · {fmtDateTime(r.setAt)}</div>
            : <div style={{ fontSize: 11, color: C.slate }}>No Cash Account rate has been saved yet. The Net Balance Sheet needs one — the Money Exchange Daily Rate is never used in its place.</div>}
          {canEditRate && <button type="button" onClick={onEditRate} style={{ background: "none", border: "none", color: C.navy, fontSize: 11.5, fontWeight: 700, cursor: "pointer", padding: 0, marginTop: 6, textDecoration: "underline", display: "inline-flex", alignItems: "center", gap: 4 }}><NavIcon name="edit" size={12} />{r ? "Edit Rate" : "Set Rate"}</button>}
        </>)}
      </>
    ), { "data-card": "rate" });
  };

  const netCard = () => {
    const cb = data && data.combined;
    const accent = C.navy;
    const reasonText = !cb ? null : cb.reason === "currency_access" ? "Needs access to both USD and SLSH."
      : cb.reason === "rate_invalid" ? "The saved Cash Account rate is not valid — set it again."
        : "Set the Cash Account exchange rate to combine USD and SLSH.";
    const eq = cb && cb.available ? (reporting === "USD" ? cb.usdEquivalent : cb.slshEquivalent) : null;
    return shell(accent, (
      <>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 6 }}>
          {head("wallet", "Net Balance Sheet", "Both Currencies Combined", accent)}
          <select aria-label="Reporting currency" value={reporting} onChange={(e) => pickReporting(e.target.value)} style={{ fontSize: 11, border: `1px solid ${C.line}`, borderRadius: 4, padding: "2px 4px", background: C.card, color: C.ink, flexShrink: 0 }}>
            <option value="SLSH">SLSH Equivalent</option><option value="USD">USD Equivalent</option>
          </select>
        </div>
        {!data ? big("…", C.ink) : !cb.available ? (
          <>
            {big(<span style={{ fontSize: 15 }}>Unavailable</span>, C.slate)}
            {breakdown(<div style={{ fontSize: 11, color: C.slate }}>{reasonText}</div>)}
          </>
        ) : (
          <>
            {big(<span className="gk-net-balance-total" data-reporting={reporting}>{money(eq.total, reporting)}</span>, eq.total < 0 ? C.red : accent)}
            <div style={{ fontSize: 10.5, color: C.slate, marginTop: -4 }}>{reporting === "SLSH" ? "SLSH Equivalent" : "USD Equivalent"} · at <span translate="no">$1 = SLSH {fmtNum(cb.rate)}</span></div>
            {breakdown(reporting === "SLSH" ? <>
              {row("USD Balance Sheet × rate", money(eq.usdConverted, "SLSH"))}
              {row("SLSH Balance Sheet", money(eq.slsh, "SLSH"), "+")}
              {row("Combined Net Balance Sheet", <b>{money(eq.total, "SLSH")}</b>, "=")}
            </> : <>
              {row("USD Balance Sheet", money(eq.usd, "USD"))}
              {row("SLSH Balance Sheet ÷ rate", money(eq.slshConverted, "USD"), "+")}
              {row("Combined Net Balance Sheet", <b>{money(eq.total, "USD")}</b>, "=")}
            </>)}
          </>
        )}
      </>
    ), { "data-card": "net" });
  };

  return (
    <div className="gk-balance-sheet" style={{ marginBottom: 18 }}>
      <div style={{ marginBottom: 8 }}>
        <div style={{ fontSize: 15, fontWeight: 700, color: C.ink, display: "flex", alignItems: "center", gap: 8 }}><NavIcon name="reports" size={17} style={{ color: C.navy }} />Balance Sheet</div>
        <div style={{ fontSize: 11.5, color: C.slate, marginTop: 2 }}>Balance Sheet = Debt + Cash Account − Credit · each currency calculated on its own</div>
      </div>
      {error ? <div role="alert" style={{ color: C.red, fontSize: 12.5 }}>Could not load the Balance Sheet. {error}</div> : (
        <div className="gk-bs-grid" style={{ display: "grid", gridTemplateColumns: "repeat(4, minmax(0, 1fr))", gap: 12 }}>
          {currencyCard("USD")}
          {currencyCard("SLSH")}
          {rateCard()}
          {netCard()}
        </div>
      )}
    </div>
  );
}

// The four Cash in Hand cards (Total USD, Total SLSH, the Cash in Hand
// Exchange Rate, Net Cash in Hand with its currency selector) — shared by the
// Cash in Hand page and the Dashboard so both always show the same thing,
// from the same /api/cash/summary response.
function CashInHandCards({ summary, baseCurrency, onBaseCurrencyChange, canEditRate, onEditRate }) {
  return (
    <div className="gk-cash-cards" style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 14, marginBottom: 18 }}>
      <StatCard label="Total Cash Account — USD" value={summary ? fmtMoney(summary.totalUSD, "USD") : "…"} accent={C.green} />
      <StatCard label="Total Cash Account — SLSH" value={summary ? fmtMoney(summary.totalSLSH, "SLSH") : "…"} accent={C.cyan} />
      <div style={{ background: C.card, border: `1px solid ${C.line}`, borderLeft: `4px solid ${C.navy}`, borderRadius: 6, padding: "16px 18px" }}>
        <div style={{ fontSize: 12.5, color: C.slate, fontWeight: 600, marginBottom: 8 }}>Exchange Rate <span style={{ fontWeight: 500, color: C.slate, fontSize: 10.5 }}>(Cash Account only)</span></div>
        <div style={{ fontFamily: FONT_MONO, fontSize: 17, color: C.ink, fontWeight: 600 }}>{summary && summary.rate ? `$1 = SLSH ${fmtNum(summary.rate)}` : "Not set"}</div>
        {canEditRate && <button onClick={onEditRate} style={{ background: "none", border: "none", color: C.navy, fontSize: 11.5, fontWeight: 700, cursor: "pointer", padding: 0, marginTop: 6, textDecoration: "underline", display: "inline-flex", alignItems: "center", gap: 4 }}><NavIcon name="edit" size={12} />Edit Rate</button>}
      </div>
      <div style={{ background: C.card, border: `1px solid ${C.line}`, borderLeft: `4px solid ${C.amber}`, borderRadius: 6, padding: "16px 18px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
          <div style={{ fontSize: 12.5, color: C.slate, fontWeight: 600 }}>Net Cash Account</div>
          <select value={baseCurrency} onChange={(e) => onBaseCurrencyChange(e.target.value)} style={{ fontSize: 11, border: `1px solid ${C.line}`, borderRadius: 4, padding: "2px 4px", background: C.card }}>
            <option value="USD">USD</option><option value="SLSH">SLSH</option>
          </select>
        </div>
        <div style={{ fontFamily: FONT_MONO, fontSize: 17, color: C.ink, fontWeight: 600 }}>{summary ? fmtMoney(summary.netCashInHand, baseCurrency) : "…"}</div>
      </div>
    </div>
  );
}

function CashInHandModule({ call, dl, notify, perm, hasRaw, onOpenCashAccountView }) {
  const [tab, setTab] = useState("accounts");
  const [summary, setSummary] = useState(null);
  // CASH IN HAND — INDEPENDENT RATE round: this module's own Exchange Rate
  // now comes from /api/cash/summary's own `rate` field (backed by
  // cash_rate_history, completely separate from the company-wide Daily
  // Rate) instead of a `rate` prop shared with the rest of the app — see
  // domain.js's getCurrentCashRate(). Edited here, via its own small modal,
  // never through the header's "Manage Rates".
  const [editRateOpen, setEditRateOpen] = useState(false);
  const [baseCurrency, setBaseCurrency] = useState("USD");
  const [accounts, setAccounts] = useState([]);
  const [accountsLoading, setAccountsLoading] = useState(true);
  const [acctCurrency, setAcctCurrency] = useState("all");
  const [acctType, setAcctType] = useState("all");
  const [acctStatus, setAcctStatus] = useState("active");
  const [acctSearch, setAcctSearch] = useState("");
  const [addAccountOpen, setAddAccountOpen] = useState(false);
  const [editAccount, setEditAccount] = useState(null);
  const [moveAccount, setMoveAccount] = useState(null); // { account, mode }

  const [movements, setMovements] = useState([]);
  const [movementsLoading, setMovementsLoading] = useState(true);
  const [moveCurrency, setMoveCurrency] = useState("all");
  const [moveType, setMoveType] = useState("all");
  const [moveSearch, setMoveSearch] = useState("");
  // CASH MOVEMENTS EDIT/DELETE round: edits an existing standalone cash
  // movement in place (via the modal below); deletion uses the same plain
  // window.confirm() pattern already used for Cash Transfers/Exchanges just
  // below in this same component, rather than a separate confirm modal.
  const [editMovement, setEditMovement] = useState(null);

  const [transfers, setTransfers] = useState([]);
  const [transferFormOpen, setTransferFormOpen] = useState(false);
  const [exchanges, setExchanges] = useState([]);
  const [exchangeFormOpen, setExchangeFormOpen] = useState(false);

  const [loans, setLoans] = useState([]);
  const [loansLoading, setLoansLoading] = useState(true);
  const [loanStatus, setLoanStatus] = useState("active");
  const [loanFormOpen, setLoanFormOpen] = useState(false);
  const [repayLoan, setRepayLoan] = useState(null);

  const canCreate = hasRaw("cash.create");
  const canManage = hasRaw("cash.update");

  const [balanceSheet, setBalanceSheet] = useState(null);
  const [balanceSheetError, setBalanceSheetError] = useState(null);
  const reloadSummary = useCallback(() => {
    call("/api/cash/summary" + qs({ base: baseCurrency })).then(setSummary).catch((e) => notify(e.message, true));
    // BALANCE SHEET round: refreshed together with the cards above, so any
    // deposit, withdrawal, payment or expense updates it too.
    setBalanceSheetError(null);
    call("/api/cash/balance-sheet").then(setBalanceSheet).catch((e) => setBalanceSheetError(e.message));
  }, [call, baseCurrency, notify]);
  useEffect(reloadSummary, [reloadSummary]);

  const reloadAccounts = useCallback(() => {
    setAccountsLoading(true);
    call("/api/cash/accounts" + qs({ currency: acctCurrency, type: acctType, status: acctStatus, search: acctSearch }))
      .then((d) => setAccounts(d.accounts || [])).catch((e) => notify(e.message, true)).finally(() => setAccountsLoading(false));
  }, [call, acctCurrency, acctType, acctStatus, acctSearch, notify]);
  useEffect(reloadAccounts, [reloadAccounts]);
  // Every account (unfiltered, active only) — used to populate the pickers
  // in Transfer/Exchange/Loan/Deposit forms regardless of the Accounts tab's
  // own filters.
  const [allActiveAccounts, setAllActiveAccounts] = useState([]);
  const reloadAllActive = useCallback(() => {
    call("/api/cash/accounts" + qs({ status: "active" })).then((d) => setAllActiveAccounts(d.accounts || [])).catch(() => {});
  }, [call]);
  useEffect(reloadAllActive, [reloadAllActive]);

  const acctSort = useSortableRows(accounts, "name", "asc");
  const acctPg = usePagination(acctSort.sorted, { initialPageSize: 10 });

  const reloadMovements = useCallback(() => {
    setMovementsLoading(true);
    call("/api/cash/ledger" + qs({ currency: moveCurrency, type: moveType, search: moveSearch }))
      .then((d) => setMovements(d.entries || [])).catch((e) => notify(e.message, true)).finally(() => setMovementsLoading(false));
  }, [call, moveCurrency, moveType, moveSearch, notify]);
  useEffect(() => { if (tab === "movements") reloadMovements(); }, [tab, reloadMovements]);
  const movePg = usePagination(movements, { initialPageSize: 10 });

  const reloadTransfers = useCallback(() => {
    call("/api/cash/transfers").then((d) => setTransfers(d.transfers || [])).catch((e) => notify(e.message, true));
  }, [call, notify]);
  useEffect(() => { if (tab === "transfers") reloadTransfers(); }, [tab, reloadTransfers]);
  const transferPg = usePagination(transfers, { initialPageSize: 10 });

  const reloadExchanges = useCallback(() => {
    call("/api/cash/exchanges").then((d) => setExchanges(d.exchanges || [])).catch((e) => notify(e.message, true));
  }, [call, notify]);
  useEffect(() => { if (tab === "exchanges") reloadExchanges(); }, [tab, reloadExchanges]);
  const exchangePg = usePagination(exchanges, { initialPageSize: 10 });

  const reloadLoans = useCallback(() => {
    setLoansLoading(true);
    call("/api/loans" + qs({ status: loanStatus })).then((d) => setLoans(d.loans || [])).catch((e) => notify(e.message, true)).finally(() => setLoansLoading(false));
  }, [call, loanStatus, notify]);
  useEffect(() => { if (tab === "loans") reloadLoans(); }, [tab, reloadLoans]);
  const loanPg = usePagination(loans, { initialPageSize: 10 });

  function reloadAll() { reloadSummary(); reloadAccounts(); reloadAllActive(); if (tab === "movements") reloadMovements(); if (tab === "transfers") reloadTransfers(); if (tab === "exchanges") reloadExchanges(); if (tab === "loans") reloadLoans(); }

  const TABS = [
    ["accounts", "Cash Accounts"], ["movements", "Cash Movements"],
    ["transfers", "Transfers"], ["exchanges", "Exchanges"], ["loans", "Loans"],
  ];

  return (
    <div>
      <SectionHeader title="Cash Account" sub="Company-owned cash across banks, mobile money, and physical cash — in USD and SLSH"
        actions={<>
          {/* Header redesign: the active tab's main action lives in the page header. */}
          {tab === "accounts" && hasRaw("cash.create") && <Btn tone="primary" onClick={() => setAddAccountOpen(true)}>+ Add Cash Account</Btn>}
          {tab === "transfers" && hasRaw("cash.transfer") && <Btn tone="transfer" onClick={() => setTransferFormOpen(true)}>+ New Cash Transfer</Btn>}
          {tab === "exchanges" && hasRaw("cash.exchange") && <Btn tone="accent" onClick={() => setExchangeFormOpen(true)}>+ New Cash Exchange</Btn>}
          {tab === "loans" && hasRaw("loans.create") && <Btn tone="primary" onClick={() => setLoanFormOpen(true)}>+ New Loan</Btn>}
        </>} />

      {/* BALANCE SHEET round: the Balance Sheet section comes first, directly
          under the page title, followed by the four original Cash in Hand cards. */}
      <BalanceSheetCard data={balanceSheet} error={balanceSheetError} canEditRate={perm("rateManage")} onEditRate={() => setEditRateOpen(true)} />

      {/* BALANCE SHEET round: same four cards, same order — only given a class
          so they wrap to 2 / 1 columns on tablets and phones (see THEME_CSS). */}
      <CashInHandCards summary={summary} baseCurrency={baseCurrency} onBaseCurrencyChange={setBaseCurrency} canEditRate={perm("rateManage")} onEditRate={() => setEditRateOpen(true)} />

      <div className="gk-tabbar">
        {TABS.map(([k, l]) => (
          <button key={k} onClick={() => setTab(k)} className={`gk-ph-tab${tab === k ? " is-active" : ""}`} aria-pressed={tab === k}><TabLabel k={k} l={l} /></button>
        ))}
      </div>

      {tab === "accounts" && (
        <>
          <div className="gk-filterbar">
            <Field label="Search" width={220}><SearchInput placeholder="Name or reference…" value={acctSearch} onChange={(e) => setAcctSearch(e.target.value)} /></Field>
            <Field label="Currency" width={130}><Select value={acctCurrency} onChange={(e) => setAcctCurrency(e.target.value)}><option value="all">All</option><option value="USD">USD</option><option value="SLSH">SLSH</option></Select></Field>
            <Field label="Account Type" width={170}><Select value={acctType} onChange={(e) => setAcctType(e.target.value)}><option value="all">All</option><option value="bank">Bank</option><option value="mobile_money">Mobile Money</option><option value="physical_cash">Physical Cash</option><option value="other">Other</option></Select></Field>
            <Field label="Status" width={140}><Select value={acctStatus} onChange={(e) => setAcctStatus(e.target.value)}><option value="all">All</option><option value="active">Active</option><option value="deactivated">Deactivated</option></Select></Field>
          </div>
          <div className="gk-table-wrap" style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 6, display: "flex", flexDirection: "column" }}>
            {accountsLoading ? <Spinner /> : acctPg.total === 0 ? (<><Empty text="No Cash Accounts Found" /><TableFooter firstIdx={acctPg.firstIdx} lastIdx={acctPg.lastIdx} total={acctPg.total} page={acctPg.page} totalPages={acctPg.totalPages} onPageChange={acctPg.setPage} pageSize={acctPg.pageSize} onPageSizeChange={acctPg.setPageSize} /></>) : (
              <>
              <TableScrollShell height={460}>
              <ResizableTable tableKey="cashInHand.accounts" className="gk-table" style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead><tr>
                  <SortTh label="Account Name" field="name" {...acctSort} onSort={acctSort.toggleSort} />
                  <SortTh label="Account Type" field="type" {...acctSort} onSort={acctSort.toggleSort} />
                  <SortTh label="Currency" field="currency" {...acctSort} onSort={acctSort.toggleSort} />
                  <SortTh label="Current Balance" field="balance" {...acctSort} onSort={acctSort.toggleSort} />
                  <SortTh label="Status" field="status" {...acctSort} onSort={acctSort.toggleSort} />
                  <SortTh label="Last Activity" field="lastActivityAt" {...acctSort} onSort={acctSort.toggleSort} />
                  <SortTh label="Actions" />
                </tr></thead>
                <tbody>
                  {acctPg.pageRows.map((a) => (
                    // CASH ACCOUNT VIEW round: clicking the row (or the
                    // account name specifically) opens this account's own
                    // dedicated Cash Account View — the exact same
                    // "whole row clickable, Actions cell stops propagation"
                    // pattern AccountsModule's own account rows already use
                    // for onOpenAccountView (see AccountsModule ~line 6789).
                    <tr key={a.id} onClick={() => onOpenCashAccountView && onOpenCashAccountView(a.id)} style={{ cursor: onOpenCashAccountView ? "pointer" : undefined }}>
                      <td style={td}>
                        <span style={{ display: "inline-flex", alignItems: "center", gap: 7, fontWeight: 700, color: onOpenCashAccountView ? C.navy : C.ink }}>
                          <NavIcon name={CASH_TYPE_ICON[a.type]} size={14} style={{ color: C.slate }} />
                          {onOpenCashAccountView ? <button type="button" onClick={(e) => { e.stopPropagation(); onOpenCashAccountView(a.id); }} style={{ background: "none", border: "none", padding: 0, font: "inherit", fontWeight: 700, color: C.navy, cursor: "pointer", textDecoration: "underline" }}>{toTitleCase(a.name)}</button> : toTitleCase(a.name)}
                        </span>
                        {a.reference && <div style={{ fontSize: 11, color: C.slate, marginLeft: 21 }}>{a.reference}</div>}
                      </td>
                      <td style={td}>{CASH_TYPE_LABEL[a.type] || a.type}</td>
                      <td style={td}><Pill tone="cyan">{a.currency}</Pill></td>
                      <td style={{ ...td, fontFamily: FONT_MONO, fontWeight: 700, fontVariantNumeric: "tabular-nums" }}>{fmtMoney(a.balance, a.currency)}</td>
                      <td style={td}>{a.status === "active" ? <Pill tone="green">Active</Pill> : <Pill tone="slate">Deactivated</Pill>}</td>
                      <td style={td}>{a.lastActivityAt ? <DateTimeCell value={a.lastActivityAt} /> : "—"}</td>
                      <td style={td} onClick={(e) => e.stopPropagation()}>
                        <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                          {hasRaw("cash.deposit") && a.status === "active" && <Btn size="sm" tone="deposit" onClick={() => setMoveAccount({ account: a, mode: "deposit" })}>Credit</Btn>}
                          {hasRaw("cash.withdraw") && a.status === "active" && <Btn size="sm" tone="withdraw" onClick={() => setMoveAccount({ account: a, mode: "withdraw" })}>Debit</Btn>}
                          {hasRaw("cash.update") && <Btn size="sm" tone="ghost" onClick={() => setEditAccount(a)}>Edit</Btn>}
                          {hasRaw("cash.deactivate") && a.status === "active" && <Btn size="sm" tone="ghost" onClick={async () => { try { await call(`/api/cash/accounts/${a.id}/deactivate`, { method: "POST" }); notify("Account deactivated."); reloadAll(); } catch (e) { notify(e.message, true); } }}>Deactivate</Btn>}
                          {hasRaw("cash.activate") && a.status === "deactivated" && <Btn size="sm" tone="ghost" onClick={async () => { try { await call(`/api/cash/accounts/${a.id}/activate`, { method: "POST" }); notify("Account reactivated."); reloadAll(); } catch (e) { notify(e.message, true); } }}>Activate</Btn>}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </ResizableTable>
              </TableScrollShell>
              <TableFooter firstIdx={acctPg.firstIdx} lastIdx={acctPg.lastIdx} total={acctPg.total} page={acctPg.page} totalPages={acctPg.totalPages} onPageChange={acctPg.setPage} pageSize={acctPg.pageSize} onPageSizeChange={acctPg.setPageSize} />
              </>
            )}
          </div>
        </>
      )}

      {tab === "movements" && (
        <>
          <div className="gk-filterbar">
            <Field label="Search" width={220}><SearchInput placeholder="Description, reference…" value={moveSearch} onChange={(e) => setMoveSearch(e.target.value)} /></Field>
            <Field label="Currency" width={130}><Select value={moveCurrency} onChange={(e) => setMoveCurrency(e.target.value)}><option value="all">All</option><option value="USD">USD</option><option value="SLSH">SLSH</option></Select></Field>
            <Field label="Type" width={150}><Select value={moveType} onChange={(e) => setMoveType(e.target.value)}><option value="all">All</option><option value="deposit">Credit</option><option value="withdrawal">Debit</option></Select></Field>
          </div>
          <div className="gk-table-wrap" style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 6, display: "flex", flexDirection: "column" }}>
            {movementsLoading ? <Spinner /> : movePg.total === 0 ? (<><Empty text="No Cash Movements Found" /><TableFooter firstIdx={movePg.firstIdx} lastIdx={movePg.lastIdx} total={movePg.total} page={movePg.page} totalPages={movePg.totalPages} onPageChange={movePg.setPage} pageSize={movePg.pageSize} onPageSizeChange={movePg.setPageSize} /></>) : (
              <>
              <TableScrollShell height={460}>
              <ResizableTable tableKey="cashInHand.movements" className="gk-table" style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead><tr><SortTh label="Date" /><SortTh label="Cash Account" /><SortTh label="Type" /><SortTh label="Description" /><SortTh label="Amount" /><SortTh label="Balance After" /><SortTh label="Reference" /><SortTh label="Staff" />{(hasRaw("cash.update") || hasRaw("cash.delete") || perm("accountsManage")) && <SortTh label="Actions" />}</tr></thead>
                <tbody>
                  {movePg.pageRows.map((e) => (
                    <tr key={e.id}>
                      <td style={td}><DateTimeCell value={e.date} /></td>
                      <td style={td}>{e.cashAccount ? e.cashAccount.name : "—"}</td>
                      <td style={td}>{e.type === "deposit" ? <Pill tone="green">Credit</Pill> : <Pill tone="red">Debit</Pill>}</td>
                      <td style={td}>{e.description || "—"}{e.counterpartyLabel && <div style={{ fontSize: 11, color: C.slate }}>To: {e.counterpartyLabel}</div>}</td>
                      <td style={{ ...td, fontFamily: FONT_MONO, fontWeight: 700, color: e.type === "deposit" ? C.green : C.red }}>{e.type === "deposit" ? "+" : "-"}{fmtMoney(e.amount, e.currency)}</td>
                      <td style={{ ...td, fontFamily: FONT_MONO }}>{fmtMoney(e.balanceAfter, e.currency)}</td>
                      <td style={{ ...td, fontFamily: FONT_MONO, fontSize: 11.5, color: C.slate }}>{e.reference || e.referenceNumber || "—"}</td>
                      <td style={td}>{e.staffName || "—"}</td>
                      {/* CASH MOVEMENTS EDIT/DELETE round: a plain, standalone
                          cash movement (e.editable, i.e. no source_type) gets
                          real Edit/Delete buttons here — the backend
                          endpoints (PATCH/DELETE /api/cash/ledger/:id)
                          already existed, this tab just never exposed them.
                          CUSTOMER-PAYMENT DELETE round: a row that's the
                          cash-side leg of a customer Payment (source_type
                          'customer_payment' — e.g. a Zaad/account Deposit
                          made with a Cash Account attached) now ALSO gets a
                          real Delete button, by request — it deletes the
                          ORIGINAL Payment via the exact same
                          DELETE /api/account-ledger/:id the Payment's own
                          module uses, which already (see routes/ledger.js)
                          removes the account-side ledger row, rebuilds that
                          customer account's balance, AND deletes this same
                          mirrored Cash in Hand leg + rebuilds the cash
                          account's balance, all in one transaction — so
                          deleting it from here is the real originating
                          Payment deletion, not a partial/local one, and
                          both sides of the money movement stay in sync
                          exactly like deleting it from the Payment side
                          would. Gated on accountsManage (the same permission
                          that endpoint itself requires), not cash.delete.
                          A Cash Transfer/Exchange/Loan leg is left exactly
                          as protected as before (rejectIfLinked on the
                          server refuses deleting those from here) — each
                          already has its own Delete in its own tab
                          (Transfers/Exchanges above; Loans has no simple
                          one-leg delete), so only a small note is shown. */}
                      {(hasRaw("cash.update") || hasRaw("cash.delete") || (e.sourceType === "customer_payment" && perm("accountsManage"))) && (
                        <td style={td}>
                          {e.editable ? (
                            <div style={{ display: "flex", gap: 4, flexWrap: "nowrap" }}>
                              {hasRaw("cash.update") && <Btn size="sm" tone="ghost" icon="edit" onClick={() => setEditMovement(e)} />}
                              {hasRaw("cash.delete") && <Btn size="sm" tone="danger" icon="trash" onClick={async () => {
                                if (!confirm(`Permanently delete this ${fmtMoney(e.amount, e.currency)} ${e.type}? This can't be undone.`)) return;
                                try { await call(`/api/cash/ledger/${e.id}`, { method: "DELETE" }); notify("Cash movement deleted."); reloadAll(); }
                                catch (err) { notify(err.message, true); }
                              }} />}
                            </div>
                          ) : e.sourceType === "customer_payment" && perm("accountsManage") ? (
                            <Btn size="sm" tone="danger" icon="trash" onClick={async () => {
                              if (!confirm(`Permanently delete the original ${fmtMoney(e.amount, e.currency)} Payment (${e.counterpartyLabel || "this account"})? This reverses BOTH the customer's account balance AND this Cash Account entry. This can't be undone.`)) return;
                              try {
                                const d = await call(`/api/account-ledger/${e.sourceId}`, { method: "DELETE" });
                                notify(d.orphanCleanup ? "That payment record was already gone — cleared this leftover Cash Account entry." : "Payment deleted — account balance and Cash Account both reversed.");
                                reloadAll();
                              } catch (err) { notify(err.message, true); }
                            }} />
                          ) : (
                            <span style={{ fontSize: 11, color: C.slate }}>Linked — see {CASH_LINKED_SOURCE_LABEL[e.sourceType] || "its source"}</span>
                          )}
                        </td>
                      )}
                    </tr>
                  ))}
                </tbody>
              </ResizableTable>
              </TableScrollShell>
              <TableFooter firstIdx={movePg.firstIdx} lastIdx={movePg.lastIdx} total={movePg.total} page={movePg.page} totalPages={movePg.totalPages} onPageChange={movePg.setPage} pageSize={movePg.pageSize} onPageSizeChange={movePg.setPageSize} />
              </>
            )}
          </div>
        </>
      )}

      {tab === "transfers" && (
        <>
          <div className="gk-table-wrap" style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 6, display: "flex", flexDirection: "column" }}>
            {transferPg.total === 0 ? (<><Empty text="No Cash Movements Found" /><TableFooter firstIdx={transferPg.firstIdx} lastIdx={transferPg.lastIdx} total={transferPg.total} page={transferPg.page} totalPages={transferPg.totalPages} onPageChange={transferPg.setPage} pageSize={transferPg.pageSize} onPageSizeChange={transferPg.setPageSize} /></>) : (
              <>
              <TableScrollShell height={420}>
              <ResizableTable tableKey="cashInHand.transfers" className="gk-table" style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead><tr><SortTh label="Date" /><SortTh label="From" /><SortTh label="To" /><SortTh label="Amount" /><SortTh label="Reference" /><SortTh label="Staff" />{hasRaw("cash.delete") && <SortTh label="Actions" />}</tr></thead>
                <tbody>
                  {transferPg.pageRows.map((t) => (
                    <tr key={t.id}>
                      <td style={td}><DateTimeCell value={t.date} /></td>
                      <td style={td}>{t.fromCashAccount ? t.fromCashAccount.name : "—"}</td>
                      <td style={td}>{t.toCashAccount ? t.toCashAccount.name : "—"}</td>
                      <td style={{ ...td, fontFamily: FONT_MONO, fontWeight: 700 }}>{fmtMoney(t.amount, t.currency)}</td>
                      <td style={{ ...td, fontFamily: FONT_MONO, fontSize: 11.5, color: C.slate }}>{t.referenceNumber}</td>
                      <td style={td}>{t.staffName}</td>
                      {hasRaw("cash.delete") && <td style={td}><Btn size="sm" tone="ghost" onClick={async () => { if (!confirm("Delete this cash transfer? This cannot be undone.")) return; try { await call(`/api/cash/transfers/${t.id}`, { method: "DELETE" }); notify("Transfer deleted."); reloadAll(); } catch (e) { notify(e.message, true); } }}>Delete</Btn></td>}
                    </tr>
                  ))}
                </tbody>
              </ResizableTable>
              </TableScrollShell>
              <TableFooter firstIdx={transferPg.firstIdx} lastIdx={transferPg.lastIdx} total={transferPg.total} page={transferPg.page} totalPages={transferPg.totalPages} onPageChange={transferPg.setPage} pageSize={transferPg.pageSize} onPageSizeChange={transferPg.setPageSize} />
              </>
            )}
          </div>
        </>
      )}

      {tab === "exchanges" && (
        <>
          <div className="gk-table-wrap" style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 6, display: "flex", flexDirection: "column" }}>
            {exchangePg.total === 0 ? (<><Empty text="No Cash Movements Found" /><TableFooter firstIdx={exchangePg.firstIdx} lastIdx={exchangePg.lastIdx} total={exchangePg.total} page={exchangePg.page} totalPages={exchangePg.totalPages} onPageChange={exchangePg.setPage} pageSize={exchangePg.pageSize} onPageSizeChange={exchangePg.setPageSize} /></>) : (
              <>
              <TableScrollShell height={420}>
              <ResizableTable tableKey="cashInHand.exchanges" className="gk-table" style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead><tr><SortTh label="Date" /><SortTh label="From" /><SortTh label="To" /><SortTh label="Given" /><SortTh label="Received" /><SortTh label="Rate" /><SortTh label="Reference" />{hasRaw("cash.delete") && <SortTh label="Actions" />}</tr></thead>
                <tbody>
                  {exchangePg.pageRows.map((x) => (
                    <tr key={x.id}>
                      <td style={td}><DateTimeCell value={x.date} /></td>
                      <td style={td}>{x.fromCashAccount ? x.fromCashAccount.name : "—"}</td>
                      <td style={td}>{x.toCashAccount ? x.toCashAccount.name : "—"}</td>
                      <td style={{ ...td, fontFamily: FONT_MONO, color: C.red }}>-{fmtMoney(x.amountGiven, x.currencyGiven)}</td>
                      <td style={{ ...td, fontFamily: FONT_MONO, color: C.green }}>+{fmtMoney(x.amountReceived, x.currencyReceived)}</td>
                      <td style={{ ...td, fontFamily: FONT_MONO, fontSize: 11.5 }}>{fmtNum(x.rateUsed)}</td>
                      <td style={{ ...td, fontFamily: FONT_MONO, fontSize: 11.5, color: C.slate }}>{x.referenceNumber}</td>
                      {hasRaw("cash.delete") && <td style={td}><Btn size="sm" tone="ghost" onClick={async () => { if (!confirm("Delete this cash exchange? This cannot be undone.")) return; try { await call(`/api/cash/exchanges/${x.id}`, { method: "DELETE" }); notify("Exchange deleted."); reloadAll(); } catch (e) { notify(e.message, true); } }}>Delete</Btn></td>}
                    </tr>
                  ))}
                </tbody>
              </ResizableTable>
              </TableScrollShell>
              <TableFooter firstIdx={exchangePg.firstIdx} lastIdx={exchangePg.lastIdx} total={exchangePg.total} page={exchangePg.page} totalPages={exchangePg.totalPages} onPageChange={exchangePg.setPage} pageSize={exchangePg.pageSize} onPageSizeChange={exchangePg.setPageSize} />
              </>
            )}
          </div>
        </>
      )}

      {tab === "loans" && (
        <>
          <div className="gk-filterbar">
            <Field label="Status" width={160}><Select value={loanStatus} onChange={(e) => setLoanStatus(e.target.value)}><option value="all">All</option><option value="active">Active</option><option value="paid">Paid</option><option value="written_off">Written Off</option></Select></Field>
          </div>
          <div className="gk-table-wrap" style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 6, display: "flex", flexDirection: "column" }}>
            {loansLoading ? <Spinner /> : loanPg.total === 0 ? (<><Empty text="No loans found." /><TableFooter firstIdx={loanPg.firstIdx} lastIdx={loanPg.lastIdx} total={loanPg.total} page={loanPg.page} totalPages={loanPg.totalPages} onPageChange={loanPg.setPage} pageSize={loanPg.pageSize} onPageSizeChange={loanPg.setPageSize} /></>) : (
              <>
              <TableScrollShell height={420}>
              <ResizableTable tableKey="cashInHand.loans" className="gk-table" style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead><tr><SortTh label="Date" /><SortTh label="Customer" /><SortTh label="Cash Account" /><SortTh label="Principal" /><SortTh label="Outstanding" /><SortTh label="Status" /><SortTh label="Reference" /><SortTh label="Actions" /></tr></thead>
                <tbody>
                  {loanPg.pageRows.map((l) => (
                    <tr key={l.id}>
                      <td style={td}><DateTimeCell value={l.date} /></td>
                      <td style={td}>{toTitleCase(l.clientName)}</td>
                      <td style={td}>{l.cashAccount ? l.cashAccount.name : "—"}</td>
                      <td style={{ ...td, fontFamily: FONT_MONO }}>{fmtMoney(l.principalAmount, l.currency)}</td>
                      <td style={{ ...td, fontFamily: FONT_MONO, fontWeight: 700, color: l.outstandingAmount > 0 ? C.red : C.green }}>{fmtMoney(l.outstandingAmount, l.currency)}</td>
                      <td style={td}>{l.status === "active" ? <Pill tone="amber">Active</Pill> : l.status === "paid" ? <Pill tone="green">Paid</Pill> : <Pill tone="slate">Written Off</Pill>}</td>
                      <td style={{ ...td, fontFamily: FONT_MONO, fontSize: 11.5, color: C.slate }}>{l.referenceNumber}</td>
                      <td style={td}>
                        <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                          {l.status === "active" && hasRaw("loans.repay") && <Btn size="sm" tone="deposit" onClick={() => setRepayLoan(l)}>Repay</Btn>}
                          {l.status === "active" && hasRaw("loans.writeOff") && <Btn size="sm" tone="ghost" onClick={async () => { if (!confirm("Write off this loan? It will no longer count toward receivables.")) return; try { await call(`/api/loans/${l.id}/write-off`, { method: "POST" }); notify("Loan written off."); reloadAll(); } catch (e) { notify(e.message, true); } }}>Write Off</Btn>}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </ResizableTable>
              </TableScrollShell>
              <TableFooter firstIdx={loanPg.firstIdx} lastIdx={loanPg.lastIdx} total={loanPg.total} page={loanPg.page} totalPages={loanPg.totalPages} onPageChange={loanPg.setPage} pageSize={loanPg.pageSize} onPageSizeChange={loanPg.setPageSize} />
              </>
            )}
          </div>
        </>
      )}

      {addAccountOpen && <CashAccountFormModal onClose={() => setAddAccountOpen(false)} onSubmit={async (body) => {
        try { await call("/api/cash/accounts", { method: "POST", body }); notify("Cash account created."); setAddAccountOpen(false); reloadAll(); }
        catch (e) { notify(e.message, true); }
      }} />}
      {editAccount && <CashAccountFormModal account={editAccount} onClose={() => setEditAccount(null)} onSubmit={async (body) => {
        try { await call(`/api/cash/accounts/${editAccount.id}`, { method: "PATCH", body }); notify("Cash account updated."); setEditAccount(null); reloadAll(); }
        catch (e) { notify(e.message, true); }
      }} />}
      {moveAccount && <CashMoveModal mode={moveAccount.mode} account={moveAccount.account} onClose={() => setMoveAccount(null)} onSubmit={async (body) => {
        try { await call(`/api/cash/accounts/${moveAccount.account.id}/${moveAccount.mode}`, { method: "POST", body }); notify(moveAccount.mode === "deposit" ? "Credit recorded." : "Debit recorded."); setMoveAccount(null); reloadAll(); }
        catch (e) { notify(e.message, true); }
      }} />}
      {editMovement && <EditCashMovementModal entry={editMovement} onClose={() => setEditMovement(null)} onSubmit={async (body) => {
        try { await call(`/api/cash/ledger/${editMovement.id}`, { method: "PATCH", body }); notify("Cash movement updated."); setEditMovement(null); reloadAll(); }
        catch (e) { notify(e.message, true); }
      }} />}
      {transferFormOpen && <CashTransferFormModal accounts={allActiveAccounts} onClose={() => setTransferFormOpen(false)} onSubmit={async (body) => {
        try { await call("/api/cash/transfers", { method: "POST", body }); notify("Cash transfer recorded."); setTransferFormOpen(false); reloadAll(); }
        catch (e) { notify(e.message, true); }
      }} />}
      {exchangeFormOpen && <CashExchangeFormModal accounts={allActiveAccounts} rate={summary && summary.rate} onClose={() => setExchangeFormOpen(false)} onSubmit={async (body) => {
        try { await call("/api/cash/exchanges", { method: "POST", body }); notify("Cash exchange recorded."); setExchangeFormOpen(false); reloadAll(); }
        catch (e) { notify(e.message, true); }
      }} />}
      {editRateOpen && <CashRateEditModal call={call} notify={notify} rate={summary && summary.rate} onSaved={() => { setEditRateOpen(false); reloadSummary(); }} onClose={() => setEditRateOpen(false)} />}
      {loanFormOpen && <LoanFormModal call={call} accounts={allActiveAccounts} onClose={() => setLoanFormOpen(false)} onSubmit={async (body) => {
        try { await call("/api/loans", { method: "POST", body }); notify("Loan recorded."); setLoanFormOpen(false); reloadAll(); }
        catch (e) { notify(e.message, true); }
      }} />}
      {repayLoan && <LoanRepayModal loan={repayLoan} accounts={allActiveAccounts} onClose={() => setRepayLoan(null)} onSubmit={async (body) => {
        try { await call(`/api/loans/${repayLoan.id}/payments`, { method: "POST", body }); notify("Repayment recorded."); setRepayLoan(null); reloadAll(); }
        catch (e) { notify(e.message, true); }
      }} />}
    </div>
  );
}

/* =========================================================================
   CASH ACCOUNT VIEW round — a dedicated, full-page, single-account
   "Cash Account View" (spec: REDESIGN CASH IN HAND — INDIVIDUAL CASH
   ACCOUNT MOVEMENTS + PDF/EXCEL EXPORT). Reached only via
   onOpenCashAccountView(id) from CashInHandModule's Cash Accounts tab (see
   App()'s "cash-account-view" branch) — structurally the same "compact
   header + summary cards + filter bar + export + ResizableTable/SortTh/
   usePagination/TableFooter" template AccountDetailModal's own Transactions
   tab already uses (app.jsx ~7107-7437), just scoped to ONE cash account's
   own cash_ledger rows (never mixed with any other account's movements —
   every fetch below is always scoped by cashAccountId) and — since
   cash_ledger already unifies every movement kind (deposit/withdrawal/
   transfer/exchange/payment/loan leg) into one per-account timeline — with
   a single Cash Movements section instead of the old Account View's five
   tabs.
   ========================================================================= */
function CashAccountDetailPage({ call, dl, notify, perm, hasRaw, cashAccountId, onBack }) {
  const [account, setAccount] = useState(null);
  const [movements, setMovements] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [moveType, setMoveType] = useState("all");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [staffId, setStaffId] = useState("");
  const [reference, setReference] = useState("");
  const [exportMenuOpen, setExportMenuOpen] = useState(false);
  const [editMovement, setEditMovement] = useState(null);

  const reloadAccount = useCallback(() => {
    call(`/api/cash/accounts/${cashAccountId}`).then((d) => setAccount(d.account)).catch((e) => notify(e.message, true));
  }, [call, cashAccountId, notify]);
  // CASH ACCOUNT VIEW round: only cashAccountId + the Date From/To filters go
  // to the server — Search/Type/Staff/Reference are applied client-side over
  // this SAME fetched array below (the exact "server scopes the window,
  // client narrows what's shown" split AccountDetailModal's own Transactions
  // tab already uses for its search/status filters), so the summary cards
  // (which must reflect the account's real Opening/Closing Balance for the
  // selected date range, never a type/search-narrowed subset) and the table
  // can never silently disagree about what "this account's movements" means.
  const reloadMovements = useCallback(() => {
    setLoading(true);
    call(`/api/cash/ledger${qs({ cashAccountId, from, to })}`)
      .then((d) => setMovements(d.entries || []))
      .catch((e) => notify(e.message, true))
      .finally(() => setLoading(false));
  }, [call, cashAccountId, from, to, notify]);
  useEffect(reloadAccount, [reloadAccount]);
  useEffect(reloadMovements, [reloadMovements]);
  function reloadAll() { reloadAccount(); reloadMovements(); }

  // Every staff member who actually appears in this account's own movements
  // — same "derive filter options from the already-loaded rows" pattern
  // ExchangeModule/TransactionHistoryModule already use for their own Staff
  // filter (see staffOptions at app.jsx ~4156/~8581), so this never needs a
  // separate /api/users call just to populate one dropdown.
  const staffOptions = useMemo(() => {
    const m = new Map();
    movements.forEach((e) => { if (e.staffId) m.set(e.staffId, e.staffName); });
    return [...m.entries()];
  }, [movements]);

  const filteredMovements = useMemo(() => {
    const q = search.trim().toLowerCase();
    return movements.filter((e) => {
      if (moveType !== "all") {
        const badge = cashMovementBadge(e);
        if (moveType === "deposit" && !(e.type === "deposit" && !e.sourceType)) return false;
        if (moveType === "withdrawal" && !(e.type === "withdrawal" && !e.sourceType)) return false;
        if (moveType === "transfer" && e.sourceType !== "cash_transfer") return false;
        if (moveType === "exchange" && !(e.sourceType === "cash_exchange" || e.sourceType === "exchange")) return false;
        if (moveType === "other" && !["loan", "loan_repayment", "customer_payment", "opening_balance"].includes(e.sourceType || "")) return false;
      }
      if (staffId && e.staffId !== staffId) return false;
      if (reference && !((e.reference || e.referenceNumber || "").toLowerCase().includes(reference.toLowerCase()))) return false;
      if (q && !(
        (e.description || "").toLowerCase().includes(q) ||
        (e.counterpartyLabel || "").toLowerCase().includes(q) ||
        (e.reference || "").toLowerCase().includes(q) ||
        (e.referenceNumber || "").toLowerCase().includes(q)
      )) return false;
      return true;
    });
  }, [movements, search, moveType, staffId, reference]);

  // RUNNING BALANCE round (spec section 6): default sort trusts the
  // backend's own newest -> oldest, `id`-tiebroken order (see cash.js's
  // `ORDER BY date DESC, created_at DESC, id DESC`) until the user explicitly
  // clicks a column header — useSortableRows then sorts whole row objects,
  // so Type/Deposit/Withdrawal/Balance After on any one row can never be
  // detached from each other.
  const moveSort = useSortableRows(filteredMovements, null, "desc");
  const movePg = usePagination(moveSort.sorted, { initialPageSize: 10 });

  // SUMMARY CARDS round (spec section 10): purely a display derivation over
  // the already-correct, already-fetched `movements` array (date-filtered
  // only, per the comment on reloadMovements above) — no new calculation,
  // nothing that could ever disagree with the real ledger.
  const summary = useMemo(() => {
    const oldest = movements.length ? movements[movements.length - 1] : null;
    const openingBalance = oldest ? oldest.balanceAfter - (oldest.type === "deposit" ? oldest.amount : -oldest.amount) : 0;
    let totalDeposits = 0, totalWithdrawals = 0, totalExchanges = 0, totalTransfers = 0;
    for (const e of movements) {
      if (e.type === "deposit") totalDeposits += e.amount; else totalWithdrawals += e.amount;
      if (e.sourceType === "cash_exchange" || e.sourceType === "exchange") totalExchanges += e.amount;
      if (e.sourceType === "cash_transfer") totalTransfers += e.amount;
    }
    return { openingBalance, totalDeposits, totalWithdrawals, totalExchanges, totalTransfers };
  }, [movements]);

  const hasFilters = search || moveType !== "all" || from || to || staffId || reference;

  // EXPORT round (spec sections 11-15): same filename-sanitizing idea the
  // spec calls for — lowercase, spaces -> hyphens, strip anything that
  // isn't alphanumeric/hyphen, and always include the account's currency
  // plus the "to" date (or today's date when no "to" filter is set).
  function exportFilename(ext) {
    const base = `cash-movements-${account.name}-${account.currency}`.toLowerCase().replace(/\s+/g, "-").replace(/[^a-z0-9-]/g, "");
    const dateTag = to || todayStr();
    return `${base}-${dateTag}.${ext}`;
  }
  function exportParams() { return qs({ from, to }); }

  if (!account && loading) return <div style={{ padding: 40 }}><Spinner /></div>;
  if (!account) return <div style={{ padding: 40 }}><Empty text="Cash account not found." /></div>;
  const isActive = account.status === "active";

  return (
    <div className="gk-account-page" style={{ background: C.paper, minHeight: "100vh", display: "flex", flexDirection: "column" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "14px 20px 0 20px" }}>
        <Btn tone="primary" size="sm" onClick={onBack}>← Back</Btn>
      </div>

      <div style={{ padding: "10px 20px 0", flexShrink: 0 }}>
        {/* CASH ACCOUNT HEADER round (spec section 2): compact identity strip —
            Name/Type/Currency/Status on the left, Current Balance + Last
            Activity on the right. Current Balance is literally
            account.balance (spec section 7) — never a separately computed
            figure. */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8, background: C.card, borderBottom: `1px solid ${C.line}`, padding: "2px 2px 6px", marginBottom: 6 }}>
          <div style={{ minWidth: 180 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
              <NavIcon name={CASH_TYPE_ICON[account.type]} size={15} style={{ color: C.slate }} />
              <div style={{ fontSize: 14, fontWeight: 700, color: C.ink, letterSpacing: "-0.01em", lineHeight: 1.15 }}>{toTitleCase(account.name)}</div>
              <span style={{ display: "inline-flex", alignItems: "center", gap: 3, fontSize: 9.5, fontWeight: 700, padding: "1px 6px", borderRadius: 20, background: isActive ? C.depositBadgeBg : C.withdrawBadgeBg, color: isActive ? C.depositBadgeText : C.withdrawBadgeText }}>
                <span style={{ width: 4, height: 4, borderRadius: "50%", background: isActive ? C.depositGreen : C.withdrawRed, display: "inline-block", flexShrink: 0 }} />
                {isActive ? "Active" : "Deactivated"}
              </span>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 5, marginTop: 2, flexWrap: "wrap" }}>
              <Pill tone="cyan">{account.currency}</Pill>
              <Pill tone="navy">{CASH_TYPE_LABEL[account.type] || account.type}</Pill>
              {account.reference && <span style={{ fontFamily: FONT_MONO, fontSize: 10.5, color: C.slate, fontWeight: 600 }}>{account.reference}</span>}
            </div>
          </div>
          <div style={{ textAlign: "right" }}>
            <div style={{ fontSize: 9.5, fontWeight: 700, color: C.slate, textTransform: "uppercase", letterSpacing: "0.04em" }}>Current Balance</div>
            <div style={{ fontFamily: FONT_MONO, fontSize: 17, fontWeight: 800, color: account.balance >= 0 ? C.balancePositive : C.balanceNegative, lineHeight: 1.05 }}>{fmtMoney(account.balance, account.currency)}</div>
            {/* AVAILABLE BALANCE round: a Cash in Hand account has no separate
                "available vs current" distinction (no holds/reservations) —
                shown as the same figure, exactly like AccountDetailModal's own
                header does for a customer account's "Available" line. */}
            <div style={{ fontSize: 10, color: C.slate, marginTop: 0 }}>Available <span style={{ fontFamily: FONT_MONO, fontWeight: 700, color: C.ink }}>{fmtMoney(account.balance, account.currency)}</span></div>
            <div style={{ fontSize: 10, color: C.slate, marginTop: 2 }}>Last Activity {account.lastActivityAt ? fmtDateTime(account.lastActivityAt) : "—"}</div>
          </div>
        </div>

        {!isActive && (
          <div style={{ marginBottom: 14, padding: "10px 12px", background: C.redBg, border: `1px solid ${C.red}`, borderRadius: 8, fontSize: 12.5, color: C.ink }}>
            <b>This Cash Account is deactivated</b> — its balance and history are preserved, but it can't take part in any new credit, debit, transfer, or exchange until it's reactivated.
            {account.deactivatedAt && <div style={{ color: C.slate, marginTop: 3 }}>Deactivated {fmtDateTime(account.deactivatedAt)}{account.deactivationReason ? ` — "${account.deactivationReason}"` : ""}</div>}
          </div>
        )}
      </div>

      <div style={{ padding: "0 20px 20px" }}>
        {/* SUMMARY CARDS round (spec section 10) */}
        <div className="gk-acct-kpi-grid" style={{ display: "grid", gridTemplateColumns: "repeat(6,1fr)", gap: 12, marginBottom: 16 }}>
          <StatCard label="Opening Balance" value={fmtMoney(summary.openingBalance, account.currency)} accent={C.navy} />
          <StatCard label="Total Credits" value={fmtMoney(summary.totalDeposits, account.currency)} accent={C.green} />
          <StatCard label="Total Debits" value={fmtMoney(summary.totalWithdrawals, account.currency)} accent={C.red} />
          <StatCard label="Total Exchanges" value={fmtMoney(summary.totalExchanges, account.currency)} accent={C.cyan} />
          <StatCard label="Total Transfers" value={fmtMoney(summary.totalTransfers, account.currency)} accent={C.transferTeal} />
          <StatCard label="Current Balance" value={fmtMoney(account.balance, account.currency)} accent={C.navy} />
        </div>

        {/* CASH MOVEMENTS TAB round (spec section 3) */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, marginBottom: 8, flexWrap: "wrap" }}>
          <div style={{ fontWeight: 700, fontSize: 14, color: C.ink }}>Cash Movements <span style={{ color: C.slate, fontWeight: 600 }}>({movePg.total})</span></div>
          <div style={{ display: "flex", gap: 6, alignItems: "center", position: "relative" }}>
            <Btn size="sm" tone="ghost" icon="refresh" onClick={reloadAll}>Refresh</Btn>
            <Btn size="sm" tone="ghost" icon="download" onClick={() => setExportMenuOpen((o) => !o)}>Export</Btn>
            {exportMenuOpen && (
              <div onMouseLeave={() => setExportMenuOpen(false)} style={{ position: "absolute", top: "calc(100% + 4px)", right: 0, background: C.card, border: `1px solid ${C.line}`, borderRadius: 6, boxShadow: "0 6px 20px rgba(8,20,30,0.15)", zIndex: 5, minWidth: 140, overflow: "hidden" }}>
                <button type="button" onClick={() => { dl(`/api/cash/accounts/${account.id}/statement.pdf${exportParams()}`, exportFilename("pdf")); setExportMenuOpen(false); }} style={{ display: "block", width: "100%", textAlign: "left", padding: "8px 12px", fontSize: 12.5, background: "transparent", border: "none", cursor: "pointer", color: C.ink }}>Export PDF</button>
                <button type="button" onClick={() => { dl(`/api/cash/accounts/${account.id}/statement.xlsx${exportParams()}`, exportFilename("xlsx")); setExportMenuOpen(false); }} style={{ display: "block", width: "100%", textAlign: "left", padding: "8px 12px", fontSize: 12.5, background: "transparent", border: "none", borderTop: `1px solid ${C.line}`, cursor: "pointer", color: C.ink }}>Export Excel</button>
              </div>
            )}
          </div>
        </div>

        {/* FILTERS round (spec section 9): Search, Movement Type, Date
            From/To, Staff, Reference — mirrors AccountDetailModal's own
            Transactions tab filter bar exactly (app.jsx ~7329-7343). Every
            filter here only ever narrows THIS account's own already-scoped
            `movements` array — never mixes in another cash account. */}
        <div className="gk-filterbar gk-filterbar--inset">
          <Field label="Search" width={170}><SearchInput value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Description, counterparty…" /></Field>
          <Field label="Movement Type" width={150}>
            <Select value={moveType} onChange={(e) => setMoveType(e.target.value)}>
              <option value="all">All</option>
              <option value="deposit">Credit</option>
              <option value="withdrawal">Debit</option>
              <option value="transfer">Transfer</option>
              <option value="exchange">Exchange</option>
              <option value="other">Other</option>
            </Select>
          </Field>
          <Field label="From" width={128}><Input type="date" value={from} onChange={(e) => setFrom(e.target.value)} /></Field>
          <Field label="To" width={128}><Input type="date" value={to} onChange={(e) => setTo(e.target.value)} /></Field>
          <Field label="Staff" width={150}><Select value={staffId} onChange={(e) => setStaffId(e.target.value)}><option value="">All staff</option>{staffOptions.map(([id, name]) => <option key={id} value={id}>{name}</option>)}</Select></Field>
          <Field label="Reference" width={150}><Input value={reference} onChange={(e) => setReference(e.target.value)} placeholder="Reference #…" /></Field>
          {hasFilters && (
            <Btn size="sm" tone="ghost" onClick={() => { setSearch(""); setMoveType("all"); setFrom(""); setTo(""); setStaffId(""); setReference(""); }}>Clear Filters</Btn>
          )}
        </div>

        <div className="gk-table-wrap" style={{ background: C.card, border: `1px solid ${C.line}`, borderRadius: 6, display: "flex", flexDirection: "column" }}>
          {loading ? <Spinner /> : movePg.total === 0 ? (
            <><Empty text="No cash movements found" /><TableFooter firstIdx={movePg.firstIdx} lastIdx={movePg.lastIdx} total={movePg.total} page={movePg.page} totalPages={movePg.totalPages} onPageChange={movePg.setPage} pageSize={movePg.pageSize} onPageSizeChange={movePg.setPageSize} /></>
          ) : (
            <>
            <TableScrollShell height={520}>
            <ResizableTable tableKey="cashAccountView.movements" className="gk-table" style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead><tr>
                <th style={{ ...th, width: 40 }}>#</th>
                <SortTh label="Date & Time" field="date" {...moveSort} onSort={moveSort.toggleSort} />
                <SortTh label="Type" />
                <SortTh label="Description" field="description" {...moveSort} onSort={moveSort.toggleSort} />
                <SortTh label="Credit" />
                <SortTh label="Debit" />
                <SortTh label="Balance After" field="balanceAfter" {...moveSort} onSort={moveSort.toggleSort} />
                <SortTh label="Reference" />
                <SortTh label="Staff" field="staffName" {...moveSort} onSort={moveSort.toggleSort} />
                <th style={{ ...th, width: 84 }}>Actions</th>
              </tr></thead>
              <tbody>
                {movePg.pageRows.map((e, i) => {
                  const badge = cashMovementBadge(e);
                  // CASH FLOW TRACEABILITY round (spec section 8): a linked
                  // movement's counterparty — its own counterpartyLabel when
                  // the backend already resolved one (e.g. "To: Abdi —
                  // Customer"), otherwise the generic CASH_LINKED_SOURCE_LABEL
                  // fallback ("Linked — see its X record"), exactly like the
                  // Cash in Hand module's own Cash Movements tab already
                  // shows (app.jsx's CASH_LINKED_SOURCE_LABEL usage).
                  const linkedNote = e.sourceType
                    ? (e.counterpartyLabel ? `${CASH_MOVEMENT_BADGE[e.sourceType]?.label || "Linked"} — ${e.counterpartyLabel}` : `Linked — see ${CASH_LINKED_SOURCE_LABEL[e.sourceType] || "its source"}`)
                    : null;
                  return (
                    <tr key={e.id}>
                      <td style={tdMono}>{movePg.firstIdx + i}</td>
                      <td style={td}><DateTimeCell value={e.date} /></td>
                      <td style={td}><Pill tone={badge.tone}>{badge.label}</Pill></td>
                      <td style={td}>
                        {e.description || "—"}
                        {linkedNote && <div style={{ fontSize: 10.5, color: C.slate, marginTop: 1 }}>{linkedNote}</div>}
                      </td>
                      <td style={{ ...tdMono, fontWeight: 700, color: e.type === "deposit" ? C.depositGreen : undefined }}>
                        {e.type === "deposit" ? `+${fmtMoney(e.amount, e.currency)}` : "—"}
                      </td>
                      <td style={{ ...tdMono, fontWeight: 700, color: e.type === "withdrawal" ? C.withdrawRed : undefined }}>
                        {e.type === "withdrawal" ? `-${fmtMoney(e.amount, e.currency)}` : "—"}
                      </td>
                      <td style={{ ...tdMono, fontWeight: 700 }}>{fmtMoney(e.balanceAfter, e.currency)}</td>
                      <td style={{ ...tdMono, fontSize: 11, color: C.slate }}>{e.reference || e.referenceNumber || "—"}</td>
                      <td style={td}>{e.staffName || "—"}</td>
                      <td style={td}>
                        {e.editable ? (
                          <div style={{ display: "flex", gap: 4, flexWrap: "nowrap" }}>
                            {hasRaw("cash.update") && <Btn size="sm" tone="ghost" icon="edit" onClick={() => setEditMovement(e)} />}
                            {hasRaw("cash.delete") && <Btn size="sm" tone="danger" icon="trash" onClick={async () => {
                              if (!confirm(`Permanently delete this ${fmtMoney(e.amount, e.currency)} ${e.type}? This can't be undone.`)) return;
                              try { await call(`/api/cash/ledger/${e.id}`, { method: "DELETE" }); notify("Cash movement deleted."); reloadAll(); }
                              catch (err) { notify(err.message, true); }
                            }} />}
                          </div>
                        ) : (
                          <span style={{ fontSize: 11, color: C.slate }}>Linked — see {CASH_LINKED_SOURCE_LABEL[e.sourceType] || "its source"}</span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </ResizableTable>
            </TableScrollShell>
            <TableFooter firstIdx={movePg.firstIdx} lastIdx={movePg.lastIdx} total={movePg.total} page={movePg.page} totalPages={movePg.totalPages} onPageChange={movePg.setPage} pageSize={movePg.pageSize} onPageSizeChange={movePg.setPageSize} />
            </>
          )}
        </div>
      </div>

      {editMovement && <EditCashMovementModal entry={editMovement} onClose={() => setEditMovement(null)} onSubmit={async (body) => {
        try { await call(`/api/cash/ledger/${editMovement.id}`, { method: "PATCH", body }); notify("Cash movement updated."); setEditMovement(null); reloadAll(); }
        catch (e) { notify(e.message, true); }
      }} />}
    </div>
  );
}

/* ---------------- mount ---------------- */
// The language lives above the app: changing it re-renders the whole
// interface in the new language at once (the app remounts; the page you are
// on, your sign-in and your company are kept).
function LangRoot() {
  const [lang, setLangState] = useState(getLang());
  const change = useCallback((next) => {
    const v = next === "so" ? "so" : "en";
    setI18nLang(v);
    try { localStorage.setItem(LANG_KEY, v); } catch (e) { /* private mode */ }
    setLangState(v);
  }, []);
  useEffect(() => { document.documentElement.lang = lang; }, [lang]);
  const ctx = useMemo(() => ({ lang, setLang: change }), [lang, change]);
  return <LangContext.Provider value={ctx}><App key={lang} /></LangContext.Provider>;
}
const root = createRoot(document.getElementById("root"));
root.render(<LangRoot />);
